-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_324b64ce95b757', 'subj_math', 'log-properties', 'Properties of logarithms', '\log_b(MN) = \log_b M + \log_b N, \ \log_b\!\frac{M}{N} = \log_b M - \log_b N, \ \log_b M^p = p\log_b M, \ \log_b M = \frac{\ln M}{\ln b}', 'Product, quotient and power rules and the change-of-base formula, for b > 0, b ≠ 1 and M, N > 0. y = log_b x means b^y = x.', '[{"symbol":"b","meaning":"base"},{"symbol":"M, N","meaning":"positive numbers"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_ad5313a2b5f8f7', 'subj_math', 'continuous-growth', 'Compound and continuous growth', 'A = P\left(1 + \frac{r}{n}\right)^{nt}, \qquad A = Pe^{rt}', 'Balance after t years at annual rate r compounded n times per year, and compounded continuously. e ≈ 2.71828.', '[{"symbol":"P","meaning":"principal"},{"symbol":"r","meaning":"annual rate (decimal)"},{"symbol":"n","meaning":"compounding periods per year"},{"symbol":"t","meaning":"years"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_0a801437037f20', 'subj_math', 'series-sums', 'Arithmetic and geometric series', 'S_n = \frac{n(a_1 + a_n)}{2}, \qquad S_n = a_1\frac{1 - r^n}{1 - r}, \qquad S_\infty = \frac{a_1}{1 - r}\ (|r| < 1)', 'Sum of the first n terms of an arithmetic series, of a geometric series (r ≠ 1), and of an infinite geometric series when |r| < 1.', '[{"symbol":"a_1","meaning":"first term"},{"symbol":"a_n","meaning":"nth term"},{"symbol":"r","meaning":"common ratio"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_d7a3ca35193c15', 'subj_math', 'complex-numbers', 'Complex numbers', 'i = \sqrt{-1},\ i^2 = -1, \quad (a + bi)(a - bi) = a^2 + b^2', 'A complex number is a + bi with real a and b. Multiplying by the conjugate gives a real number, which is used to divide complex numbers.', '[{"symbol":"a","meaning":"real part"},{"symbol":"b","meaning":"imaginary part"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_fa2d686a003d99', 'subj_math', 'sinusoid', 'Sinusoidal function', 'y = A\sin\big(B(x - C)\big) + D, \quad \text{period} = \frac{2\pi}{|B|}', 'Amplitude |A|, period 2π/|B|, phase (horizontal) shift C and midline y = D. The same holds for cosine.', '[{"symbol":"A","meaning":"amplitude factor"},{"symbol":"B","meaning":"frequency factor"},{"symbol":"C","meaning":"phase shift"},{"symbol":"D","meaning":"midline"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_2b6aa3b35a425e', 'subj_math', 'binomial-theorem', 'Binomial Theorem', '(a + b)^n = \sum_{k=0}^{n} \binom{n}{k} a^{n-k} b^k', 'Expansion of a binomial power; the coefficients are the entries in row n of Pascal''s triangle.', '[{"symbol":"\\binom{n}{k}","meaning":"n choose k = n!/(k!(n − k)!)"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_3a420a076cbe34', 'subj_math', 'margin-of-error', 'Margin of error (proportion)', '\text{ME} \approx z^*\sqrt{\frac{\hat{p}(1 - \hat{p})}{n}} \approx \frac{1}{\sqrt{n}} \ \ (95\%,\ \text{worst case})', 'Approximate margin of error for a sample proportion from a simple random sample; z* ≈ 1.96 for 95% confidence.', '[{"symbol":"\\hat{p}","meaning":"sample proportion"},{"symbol":"n","meaning":"sample size"}]', 'published');

-- Lesson: amplitude-period-phase
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_dd39af31855458', 'amplitude-period-phase', 'Amplitude, period and phase shift', 'Graph y = A sin(B(x − C)) + D, read its amplitude, period, phase shift and midline, and write a sinusoidal model from a graph or situation.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6061480cae8265', 'les_dd39af31855458', 1, 'Identify amplitude, period, phase shift and midline from an equation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0b70ad155fd4e5', 'les_dd39af31855458', 2, 'Graph a transformed sine or cosine.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_855fa26d8755e4', 'les_dd39af31855458', 3, 'Write a sinusoidal model from a graph or real data.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6061480cae8265', 'les_dd39af31855458', 'learn', 1, 'definition', '{"term":"Parameters","body":"In $y = A\\sin(B(x - C)) + D$: amplitude $|A|$; period $\\frac{2\\pi}{|B|}$; phase shift $C$ (right if $C > 0$); midline $y = D$. Max $D + |A|$, min $D - |A|$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0b70ad155fd4e5', 'les_dd39af31855458', 'experiment', 2, 'activity', '{"activity":"sinusoid","title":"Change one parameter at a time","params":{"A":2,"B":2,"C":0.8,"D":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_855fa26d8755e4', 'les_dd39af31855458', 'experiment', 3, 'callout', '{"tone":"tip","title":"Try this","body":"Change only B and watch the period readout: doubling B halves the period. Then change C: the whole wave slides without changing shape."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7b9b42a3867d1f', 'les_dd39af31855458', 'learn', 4, 'worked_example', '{"title":"Describe $y = 3\\cos\\left(2\\left(x - \\tfrac{\\pi}{4}\\right)\\right) - 1$","steps":[{"latex":"\\text{amplitude } 3,\\ \\text{period } \\pi","explanation":""},{"latex":"\\text{shift right } \\tfrac{\\pi}{4},\\ \\text{midline } y = -1","explanation":"Max 2, min −4."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b3af05dadb1a6a', 'les_dd39af31855458', 'learn', 5, 'worked_example', '{"title":"A Ferris wheel 40 m across has its center 25 m up and turns once every 8 minutes. A rider starts at the bottom. Model height.","steps":[{"latex":"A = 20,\\ D = 25,\\ B = \\tfrac{2\\pi}{8} = \\tfrac{\\pi}{4}","explanation":""},{"latex":"h(t) = -20\\cos\\left(\\tfrac{\\pi}{4}t\\right) + 25","explanation":"Starting at the bottom: a negative cosine."}],"check":"Check: $h(0) = 5$ m (bottom) and $h(4) = 45$ m (top)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04f7f9ca39520c', 'les_dd39af31855458', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Tide tables, temperature cycles, sound frequencies (B sets the pitch) and biological rhythms are modeled with these four parameters."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6061480cae8265', 'les_dd39af31855458', 1, 'practice', 'numeric', 1, 'What is the amplitude of $y = -5\sin(3x)$?', '{"answer":5}', '[]', '5.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0b70ad155fd4e5', 'les_dd39af31855458', 2, 'practice', 'short_text', 2, 'What is the period of $y = \sin(4x)$? Use the format pi/2.', '{"accept":["pi/2","π/2"]}', '[]', '$\frac{2\pi}{4} = \frac{\pi}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_855fa26d8755e4', 'les_dd39af31855458', 3, 'practice', 'multiple_choice', 2, 'What is the phase shift of $y = \cos\left(x + \frac{\pi}{3}\right)$?', '{"choices":["$\\frac{\\pi}{3}$ right","$\\frac{\\pi}{3}$ left","$3$ left","None"],"answer":1}', '[]', '$x + \frac{\pi}{3} = x - \left(-\frac{\pi}{3}\right)$: left $\frac{\pi}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7b9b42a3867d1f', 'les_dd39af31855458', 4, 'practice', 'numeric', 2, 'What is the minimum value of $y = 4\sin x + 7$?', '{"answer":3}', '[]', '$7 - 4 = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b3af05dadb1a6a', 'les_dd39af31855458', 5, 'review', 'numeric', 3, 'High tide is 9 m and low tide is 3 m, 6.2 hours apart. What is the amplitude in meters?', '{"answer":3,"unit":"m"}', '[]', '$\frac{9 - 3}{2} = 3$ (midline 6, period 12.4 h).');
