-- Lesson: arithmetic-series
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_016c6a5141a002', 'arithmetic-series', 'Arithmetic sequences and series', 'Review arithmetic sequences and find the sum of an arithmetic series with Gauss''s pairing method.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c400330ef23a80', 'les_016c6a5141a002', 1, 'Write explicit and recursive rules for arithmetic sequences.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2a7623d442b378', 'les_016c6a5141a002', 2, 'Derive and use S_n = n(a₁ + aₙ)/2.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c33d8d52aaeb17', 'les_016c6a5141a002', 3, 'Solve problems about totals that grow by a constant amount.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c400330ef23a80', 'les_016c6a5141a002', 'learn', 1, 'definition', '{"term":"Series","body":"A series is the sum of the terms of a sequence. $S_n$ is the sum of the first $n$ terms."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2a7623d442b378', 'les_016c6a5141a002', 'learn', 2, 'text', '{"body":"Legend says young Gauss summed 1 to 100 instantly. Write the sum forwards and backwards and add: each column is $1 + 100 = 101$, and there are 100 columns, so twice the sum is $100 \\cdot 101$, and the sum is 5050. The same pairing works for any arithmetic series."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c33d8d52aaeb17', 'les_016c6a5141a002', 'learn', 3, 'definition', '{"term":"Arithmetic series sum","body":"$S_n = \\dfrac{n(a_1 + a_n)}{2}$: the number of terms times the average of the first and last terms. With $a_n = a_1 + (n - 1)d$, also $S_n = \\frac{n}{2}[2a_1 + (n - 1)d]$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ccb494d07d4ab9', 'les_016c6a5141a002', 'learn', 4, 'worked_example', '{"title":"Find the sum of the first 40 terms of 7, 11, 15, …","steps":[{"latex":"a_{40} = 7 + 39 \\cdot 4 = 163","explanation":""},{"latex":"S_{40} = \\tfrac{40(7 + 163)}{2} = 3400","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_247973ad7d6d65', 'les_016c6a5141a002', 'learn', 5, 'worked_example', '{"title":"A theater has 25 rows. Row 1 has 20 seats and each row has 2 more. How many seats in all?","steps":[{"latex":"a_{25} = 20 + 24 \\cdot 2 = 68","explanation":""},{"latex":"S_{25} = \\tfrac{25(20 + 68)}{2} = 1100","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97aadcafbacb9a', 'les_016c6a5141a002', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Stacked objects (cans in a pyramid display), savings plans with steadily increasing deposits, and the distance a car travels while accelerating evenly second by second."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c400330ef23a80', 'les_016c6a5141a002', 1, 'practice', 'numeric', 1, 'Find $1 + 2 + 3 + \cdots + 50$.', '{"answer":1275}', '[]', '$\frac{50 \cdot 51}{2} = 1275$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2a7623d442b378', 'les_016c6a5141a002', 2, 'practice', 'numeric', 2, 'Find the sum of the first 20 terms of 3, 8, 13, …', '{"answer":1010}', '["$a_{20} = 98$."]', '$\frac{20(3 + 98)}{2} = 1010$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c33d8d52aaeb17', 'les_016c6a5141a002', 3, 'practice', 'numeric', 2, 'Find the sum of the odd numbers from 1 to 99.', '{"answer":2500}', '["50 terms."]', '$\frac{50(1 + 99)}{2} = 2500$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ccb494d07d4ab9', 'les_016c6a5141a002', 4, 'review', 'numeric', 3, 'An arithmetic series has $a_1 = 4$, $d = 3$ and $S_n = 175$. Find $n$.', '{"answer":10}', '["$\\frac{n}{2}[8 + 3(n - 1)] = 175$."]', '$3n^2 + 5n - 350 = 0$, $n = 10$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_016c6a5141a002', (SELECT id FROM concepts WHERE slug = 'arithmetic-sequences'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8c45d090913a21', 'subj_math', 'series', 'Series', 'The sum of the terms of a sequence.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_016c6a5141a002', (SELECT id FROM concepts WHERE slug = 'series'));
