-- Lesson: binomial-theorem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2b6aa3b35a425e', 'binomial-theorem', 'The Binomial Theorem', 'Expand powers of binomials with Pascal''s triangle and combinations, and find a specific term without expanding everything.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_652ee2b966efa0', 'les_2b6aa3b35a425e', 1, 'Build Pascal''s triangle and connect its entries to combinations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bbbb4abb666d69', 'les_2b6aa3b35a425e', 2, 'Expand (a + b)^n with the Binomial Theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7c51b0ad8c55b7', 'les_2b6aa3b35a425e', 3, 'Find a specific term or coefficient of an expansion.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_652ee2b966efa0', 'les_2b6aa3b35a425e', 'learn', 1, 'text', '{"body":"Expanding $(a + b)^n$ means choosing $a$ or $b$ from each of the $n$ factors. The term $a^{n-k}b^k$ appears once for each way to choose which $k$ factors contribute a $b$, which is $\\binom{n}{k}$ ways. That''s the whole theorem."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bbbb4abb666d69', 'les_2b6aa3b35a425e', 'learn', 2, 'definition', '{"term":"Binomial Theorem","body":"$(a + b)^n = \\sum_{k=0}^{n} \\binom{n}{k} a^{n-k} b^k$. The coefficients form row $n$ of Pascal''s triangle (1; 1 1; 1 2 1; 1 3 3 1; 1 4 6 4 1; …), where each entry is the sum of the two above it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c51b0ad8c55b7', 'les_2b6aa3b35a425e', 'learn', 3, 'worked_example', '{"title":"Expand $(x - 2)^4$","steps":[{"latex":"\\binom{4}{k}: 1, 4, 6, 4, 1","explanation":""},{"latex":"x^4 + 4x^3(-2) + 6x^2(4) + 4x(-8) + 16","explanation":""},{"latex":"x^4 - 8x^3 + 24x^2 - 32x + 16","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e085cbdf462880', 'les_2b6aa3b35a425e', 'learn', 4, 'worked_example', '{"title":"Find the $x^3$ term of $(2x + 1)^7$","steps":[{"latex":"\\binom{7}{4}(2x)^3(1)^4","explanation":"The term with (2x)³ has k = 4 factors of 1."},{"latex":"35 \\cdot 8x^3 = 280x^3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_febfdb305962fc', 'les_2b6aa3b35a425e', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Binomial probabilities (exactly k successes in n trials), approximations like $(1.01)^{10} \\approx 1 + 10(0.01) + 45(0.0001) = 1.1045$, and counting paths on a grid all use binomial coefficients."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_652ee2b966efa0', 'les_2b6aa3b35a425e', 1, 'practice', 'numeric', 1, 'Evaluate $\binom{6}{2}$.', '{"answer":15}', '[]', '15.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bbbb4abb666d69', 'les_2b6aa3b35a425e', 2, 'practice', 'short_text', 2, 'Expand $(x + 1)^3$.', '{"accept":["x^3+3x^2+3x+1"]}', '[]', '$x^3 + 3x^2 + 3x + 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c51b0ad8c55b7', 'les_2b6aa3b35a425e', 3, 'practice', 'numeric', 2, 'Find the coefficient of $x^2$ in $(x + 3)^5$.', '{"answer":270}', '["$\\binom{5}{3}3^3$."]', '$10 \cdot 27 = 270$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e085cbdf462880', 'les_2b6aa3b35a425e', 4, 'review', 'numeric', 3, 'Find the coefficient of $x^4$ in $(2x - 1)^6$.', '{"answer":240}', '["$\\binom{6}{2}(2)^4(-1)^2$."]', '$15 \cdot 16 = 240$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2b6aa3b35a425e', 'subj_math', 'binomial-theorem', 'Binomial Theorem', 'A formula for expanding (a + b)^n using combinations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2b6aa3b35a425e', (SELECT id FROM concepts WHERE slug = 'binomial-theorem'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2b6aa3b35a425e', (SELECT id FROM concepts WHERE slug = 'counting'));
