-- Lesson: complex-numbers
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d7a3ca35193c15', 'complex-numbers', 'Imaginary and complex numbers', 'Define i, simplify square roots of negatives and powers of i, and add, subtract, multiply and divide complex numbers.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_76f15bdb17b13d', 'les_d7a3ca35193c15', 1, 'Define i and write square roots of negative numbers in terms of i.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_64aaf02a6be055', 'les_d7a3ca35193c15', 2, 'Simplify powers of i using the cycle i, −1, −i, 1.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c6075f796bbd27', 'les_d7a3ca35193c15', 3, 'Add, subtract, multiply and divide complex numbers, using conjugates to divide.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_76f15bdb17b13d', 'les_d7a3ca35193c15', 'learn', 1, 'text', '{"body":"No real number squares to $-1$. Mathematicians defined a new number $i$ with $i^2 = -1$ and found that the rules of algebra still work. With $i$, every quadratic equation has solutions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_64aaf02a6be055', 'les_d7a3ca35193c15', 'learn', 2, 'definition', '{"term":"Complex numbers","body":"$\\sqrt{-k} = i\\sqrt{k}$ for $k > 0$. A complex number is $a + bi$ with real part $a$ and imaginary part $b$. Real numbers ($b = 0$) and pure imaginary numbers ($a = 0$) are special cases."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c6075f796bbd27', 'les_d7a3ca35193c15', 'learn', 3, 'definition', '{"term":"Powers of i","body":"$i^1 = i$, $i^2 = -1$, $i^3 = -i$, $i^4 = 1$, then the cycle repeats. To simplify $i^n$, divide $n$ by 4 and use the remainder: $i^{23} = i^{3} = -i$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_34b6d429779c6a', 'les_d7a3ca35193c15', 'learn', 4, 'worked_example', '{"title":"Multiply $(3 + 2i)(4 - 5i)$","steps":[{"latex":"12 - 15i + 8i - 10i^2","explanation":"Distribute (FOIL)."},{"latex":"12 - 7i + 10 = 22 - 7i","explanation":"$-10i^2 = +10$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4a7b932eb97cf', 'les_d7a3ca35193c15', 'learn', 5, 'worked_example', '{"title":"Divide $\\dfrac{5 + i}{2 - 3i}$","steps":[{"latex":"\\frac{5 + i}{2 - 3i} \\cdot \\frac{2 + 3i}{2 + 3i}","explanation":"Multiply by the conjugate of the denominator."},{"latex":"\\frac{10 + 15i + 2i + 3i^2}{4 + 9} = \\frac{7 + 17i}{13}","explanation":""},{"latex":"\\tfrac{7}{13} + \\tfrac{17}{13}i","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_98a77c0c8da465', 'les_d7a3ca35193c15', 'learn', 6, 'callout', '{"tone":"warning","title":"Simplify roots of negatives first","body":"$\\sqrt{-4} \\cdot \\sqrt{-9} = 2i \\cdot 3i = 6i^2 = -6$, not $\\sqrt{36} = 6$. The rule $\\sqrt{a}\\sqrt{b} = \\sqrt{ab}$ only holds when $a, b \\ge 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ef8c029cae0fbf', 'les_d7a3ca35193c15', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Electrical engineers describe AC circuits with complex numbers, signal processing (audio, images, Wi-Fi) runs on them, and quantum mechanics is written in them."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_76f15bdb17b13d', 'les_d7a3ca35193c15', 1, 'practice', 'short_text', 1, 'Simplify $\sqrt{-49}$.', '{"accept":["7i"]}', '[]', '$7i$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_64aaf02a6be055', 'les_d7a3ca35193c15', 2, 'practice', 'short_text', 2, 'Simplify $(6 - 2i) - (1 + 5i)$.', '{"accept":["5-7i"]}', '[]', '$5 - 7i$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c6075f796bbd27', 'les_d7a3ca35193c15', 3, 'practice', 'short_text', 2, 'Multiply $(2 + i)(3 - i)$.', '{"accept":["7+i"]}', '["$6 - 2i + 3i - i^2$."]', '$6 + i + 1 = 7 + i$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_34b6d429779c6a', 'les_d7a3ca35193c15', 4, 'practice', 'multiple_choice', 2, 'Simplify $i^{50}$.', '{"choices":["1","i","−1","−i"],"answer":2}', '["50 = 4 · 12 + 2."]', '$i^2 = -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4a7b932eb97cf', 'les_d7a3ca35193c15', 5, 'review', 'numeric', 3, 'What is the product of $4 + 3i$ and its conjugate?', '{"answer":25}', '["$a^2 + b^2$."]', '$16 + 9 = 25$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d7a3ca35193c15', 'subj_math', 'complex-numbers', 'Complex numbers', 'Numbers a + bi with real a and b, where i² = −1.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d7a3ca35193c15', (SELECT id FROM concepts WHERE slug = 'complex-numbers'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d7a3ca35193c15', (SELECT id FROM formulas WHERE slug = 'complex-numbers'), 1);

-- Lesson: composition-of-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c33c5766848989', 'composition-of-functions', 'Composition of functions', 'Evaluate and write compositions f(g(x)), see that order matters, find domains of compositions, and decompose a function into simpler pieces.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_56356e7cb4ddea', 'les_c33c5766848989', 1, 'Evaluate f(g(a)) from equations, tables and graphs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7c135dd3ea5fba', 'les_c33c5766848989', 2, 'Write a formula for f ∘ g and g ∘ f and compare them.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7b11a0a9a511d0', 'les_c33c5766848989', 3, 'Find the domain of a composition and decompose a function as a composition.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_56356e7cb4ddea', 'les_c33c5766848989', 'learn', 1, 'definition', '{"term":"Composition","body":"$(f \\circ g)(x) = f(g(x))$: apply $g$ first, then $f$ to the result. Read it inside out."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c135dd3ea5fba', 'les_c33c5766848989', 'learn', 2, 'worked_example', '{"title":"$f(x) = x^2 + 1$ and $g(x) = 2x - 3$. Find $f(g(2))$, $f(g(x))$ and $g(f(x))$.","steps":[{"latex":"g(2) = 1,\\ f(1) = 2","explanation":"Inside first."},{"latex":"f(g(x)) = (2x - 3)^2 + 1 = 4x^2 - 12x + 10","explanation":""},{"latex":"g(f(x)) = 2(x^2 + 1) - 3 = 2x^2 - 1","explanation":"Different: order matters."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7b11a0a9a511d0', 'les_c33c5766848989', 'learn', 3, 'text', '{"body":"The domain of $f \\circ g$ is all $x$ in the domain of $g$ for which $g(x)$ is in the domain of $f$. For $f(x) = \\sqrt{x}$ and $g(x) = x - 5$, $f(g(x)) = \\sqrt{x - 5}$ needs $x \\ge 5$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4bb1f73f71664', 'les_c33c5766848989', 'learn', 4, 'worked_example', '{"title":"Decompose $h(x) = \\sqrt{3x + 7}$","steps":[{"latex":"g(x) = 3x + 7,\\ f(x) = \\sqrt{x}","explanation":"The inner operation and the outer one."},{"latex":"h = f \\circ g","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_36028b890db5f8', 'les_c33c5766848989', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Unit conversions chain as compositions (inches → centimeters → meters), a discount then a tax is a composition, and computer programs pass one function''s output into another constantly."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_56356e7cb4ddea', 'les_c33c5766848989', 1, 'practice', 'numeric', 1, '$f(x) = x + 4$, $g(x) = 3x$. Find $f(g(2))$.', '{"answer":10}', '[]', '$g(2) = 6$, $f(6) = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c135dd3ea5fba', 'les_c33c5766848989', 2, 'practice', 'numeric', 1, 'Same functions: find $g(f(2))$.', '{"answer":18}', '[]', '$f(2) = 6$, $g(6) = 18$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7b11a0a9a511d0', 'les_c33c5766848989', 3, 'practice', 'short_text', 2, '$f(x) = x^2$, $g(x) = x - 1$. Write $f(g(x))$ expanded.', '{"accept":["x^2-2x+1"]}', '[]', '$(x - 1)^2 = x^2 - 2x + 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e4bb1f73f71664', 'les_c33c5766848989', 4, 'practice', 'short_text', 2, 'Same functions: write $g(f(x))$.', '{"accept":["x^2-1"]}', '[]', '$x^2 - 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_36028b890db5f8', 'les_c33c5766848989', 5, 'review', 'multiple_choice', 3, 'A store takes 20% off ($d(p) = 0.8p$) and then adds 8% tax ($t(p) = 1.08p$). Which composition gives the final price?', '{"choices":["$d(t(p))$","$t(d(p))$","$d(p) + t(p)$","Both orders give the same, 0.864p"],"answer":3}', '["Multiply the factors."]', 'Both compositions equal $0.864p$ because multiplication is commutative; here order doesn''t matter.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7925a166f49db8', 'subj_math', 'function-operations', 'Function operations', 'Combining functions by adding, subtracting, multiplying, dividing or composing.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c33c5766848989', (SELECT id FROM concepts WHERE slug = 'function-operations'));

-- Lesson: determinants-inverses
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_eb9ddc39f94448', 'determinants-inverses', 'Determinants and inverses', 'Compute 2 × 2 and 3 × 3 determinants, interpret them as area scale factors, and find the inverse of a 2 × 2 matrix.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c93b3976870131', 'les_eb9ddc39f94448', 1, 'Compute determinants of 2 × 2 and 3 × 3 matrices.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ad19b0f86d2da3', 'les_eb9ddc39f94448', 2, 'Interpret the determinant as an area scaling factor.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f7182b82c6300d', 'les_eb9ddc39f94448', 3, 'Find the inverse of a 2 × 2 matrix and decide when no inverse exists.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c93b3976870131', 'les_eb9ddc39f94448', 'learn', 1, 'definition', '{"term":"2 × 2 determinant","body":"$\\det\\begin{bmatrix} a & b \\\\ c & d \\end{bmatrix} = ad - bc$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad19b0f86d2da3', 'les_eb9ddc39f94448', 'learn', 2, 'text', '{"body":"Geometrically, the matrix sends the unit square to a parallelogram, and $|\\det|$ is that parallelogram''s area. A determinant of 0 means the square is flattened onto a line, information is lost, and the matrix can''t be undone."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f7182b82c6300d', 'les_eb9ddc39f94448', 'learn', 3, 'definition', '{"term":"2 × 2 inverse","body":"If $ad - bc \\ne 0$: $\\begin{bmatrix} a & b \\\\ c & d \\end{bmatrix}^{-1} = \\frac{1}{ad - bc}\\begin{bmatrix} d & -b \\\\ -c & a \\end{bmatrix}$. Then $AA^{-1} = A^{-1}A = I$, the identity matrix."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_03090d510426eb', 'les_eb9ddc39f94448', 'learn', 4, 'worked_example', '{"title":"Find the inverse of $A = \\begin{bmatrix} 4 & 7 \\\\ 2 & 6 \\end{bmatrix}$","steps":[{"latex":"\\det A = 24 - 14 = 10","explanation":""},{"latex":"A^{-1} = \\tfrac{1}{10}\\begin{bmatrix} 6 & -7 \\\\ -2 & 4 \\end{bmatrix} = \\begin{bmatrix} 0.6 & -0.7 \\\\ -0.2 & 0.4 \\end{bmatrix}","explanation":""}],"check":"Check the top-left entry of $AA^{-1}$: $4(0.6) + 7(-0.2) = 1$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_beed2f8610e3c2', 'les_eb9ddc39f94448', 'learn', 5, 'definition', '{"term":"3 × 3 determinant","body":"Expand along the first row: $a(ei - fh) - b(di - fg) + c(dh - eg)$ for $\\begin{bmatrix} a & b & c \\\\ d & e & f \\\\ g & h & i \\end{bmatrix}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a3fb6940b66d6', 'les_eb9ddc39f94448', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Determinants find areas of triangles from coordinates ($\\frac{1}{2}|\\det|$), tell whether a system has a unique solution, and appear in cryptography (Hill ciphers) and 3D graphics."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c93b3976870131', 'les_eb9ddc39f94448', 1, 'practice', 'numeric', 1, 'Find $\det\begin{bmatrix} 3 & 5 \\ 1 & 2 \end{bmatrix}$.', '{"answer":1}', '[]', '$6 - 5 = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ad19b0f86d2da3', 'les_eb9ddc39f94448', 2, 'practice', 'multiple_choice', 2, 'Which matrix has no inverse?', '{"choices":["$\\begin{bmatrix} 1 & 2 \\\\ 3 & 4 \\end{bmatrix}$","$\\begin{bmatrix} 2 & 4 \\\\ 1 & 2 \\end{bmatrix}$","$\\begin{bmatrix} 1 & 0 \\\\ 0 & 1 \\end{bmatrix}$","$\\begin{bmatrix} 0 & 1 \\\\ 1 & 0 \\end{bmatrix}$"],"answer":1}', '[]', '$4 - 4 = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f7182b82c6300d', 'les_eb9ddc39f94448', 3, 'practice', 'numeric', 2, 'What is the top-left entry of the inverse of $\begin{bmatrix} 2 & 1 \\ 5 & 3 \end{bmatrix}$?', '{"answer":3}', '["det = 1."]', '$\frac{1}{1}\begin{bmatrix} 3 & -1 \\ -5 & 2 \end{bmatrix}$: 3.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_03090d510426eb', 'les_eb9ddc39f94448', 4, 'review', 'numeric', 3, 'Find $\det\begin{bmatrix} 1 & 2 & 0 \\ 0 & 3 & 1 \\ 2 & 1 & 4 \end{bmatrix}$.', '{"answer":15}', '["Expand along row 1."]', '$1(3 \cdot 4 - 1 \cdot 1) - 2(0 \cdot 4 - 1 \cdot 2) + 0 = 11 + 4 = 15$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_cebd95d917358f', 'subj_math', 'matrices', 'Matrices', 'Rectangular arrays of numbers with their own arithmetic.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_eb9ddc39f94448', (SELECT id FROM concepts WHERE slug = 'matrices'));

-- Lesson: dividing-polynomials
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_706efd3fab46a0', 'dividing-polynomials', 'Dividing polynomials', 'Divide polynomials by long division and by synthetic division, and write the result as quotient plus remainder over divisor.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1a32cfffbe520c', 'les_706efd3fab46a0', 1, 'Divide a polynomial by a polynomial using long division.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1983e71278f82a', 'les_706efd3fab46a0', 2, 'Use synthetic division to divide by x − c.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b38a179f4f837e', 'les_706efd3fab46a0', 3, 'Write the division result as P(x) = D(x)Q(x) + R(x).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a32cfffbe520c', 'les_706efd3fab46a0', 'learn', 1, 'text', '{"body":"Polynomial long division works like long division of numbers: divide the leading terms, multiply, subtract, bring down, repeat. Write missing powers with zero coefficients so the columns line up."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1983e71278f82a', 'les_706efd3fab46a0', 'learn', 2, 'worked_example', '{"title":"Divide $2x^3 + 3x^2 - 5x + 6$ by $x + 3$","steps":[{"latex":"2x^3 \\div x = 2x^2;\\ \\ 2x^2(x + 3) = 2x^3 + 6x^2","explanation":"Subtract: −3x² − 5x."},{"latex":"-3x^2 \\div x = -3x;\\ \\ -3x(x + 3) = -3x^2 - 9x","explanation":"Subtract: 4x + 6."},{"latex":"4x \\div x = 4;\\ \\ 4(x + 3) = 4x + 12","explanation":"Subtract: remainder −6."},{"latex":"2x^2 - 3x + 4 - \\frac{6}{x + 3}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b38a179f4f837e', 'les_706efd3fab46a0', 'learn', 3, 'definition', '{"term":"Synthetic division","body":"A shortcut for dividing by $x - c$: write $c$ and the coefficients. Bring down the first coefficient; repeatedly multiply by $c$, write the product under the next coefficient, and add. The last number is the remainder; the others are the quotient''s coefficients, one degree lower."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97a314ca6ce93c', 'les_706efd3fab46a0', 'learn', 4, 'worked_example', '{"title":"Divide $x^3 - 7x + 6$ by $x - 2$ synthetically","steps":[{"latex":"2 \\,|\\, 1 \\quad 0 \\quad -7 \\quad 6","explanation":"Include 0 for the missing x² term."},{"latex":"\\phantom{2 \\,|\\,} 1 \\quad 2 \\quad -3 \\quad 0","explanation":"Down 1; 1·2 = 2, 0 + 2 = 2; 2·2 = 4, −7 + 4 = −3; −3·2 = −6, 6 − 6 = 0."},{"latex":"x^2 + 2x - 3,\\ \\text{remainder } 0","explanation":"x − 2 is a factor."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_226ed074d631dd', 'les_706efd3fab46a0', 'learn', 5, 'callout', '{"tone":"warning","title":"Use c, not −c","body":"For $x + 3$, use $c = -3$ in synthetic division. Synthetic division only works for divisors of the form $x - c$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c30f47725b9c76', 'les_706efd3fab46a0', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Division simplifies rational functions, finds slant asymptotes, and factors polynomials once one zero is known. Error-checking codes in digital communication use polynomial division too."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1a32cfffbe520c', 'les_706efd3fab46a0', 1, 'practice', 'short_text', 2, 'Divide $x^2 + 7x + 12$ by $x + 3$.', '{"accept":["x+4"]}', '[]', '$x + 4$, remainder 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1983e71278f82a', 'les_706efd3fab46a0', 2, 'practice', 'numeric', 2, 'Find the remainder when $x^3 - 2x^2 + 4$ is divided by $x - 3$.', '{"answer":13}', '["Synthetic division with c = 3."]', 'Coefficients 1, −2, 0, 4: 1, 1, 3, 13. Remainder 13.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b38a179f4f837e', 'les_706efd3fab46a0', 3, 'practice', 'short_text', 2, 'Divide $2x^3 - 5x^2 + x + 2$ by $x - 2$. Enter the quotient.', '{"accept":["2x^2-x-1"]}', '[]', '2, −1, −1 with remainder 0: $2x^2 - x - 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97a314ca6ce93c', 'les_706efd3fab46a0', 4, 'review', 'numeric', 3, 'Find the remainder when $x^4 - 1$ is divided by $x + 1$.', '{"answer":0}', '["Coefficients 1, 0, 0, 0, −1, c = −1."]', '1, −1, 1, −1, 0: remainder 0.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_bdebb0664fa40f', 'subj_math', 'polynomial-division', 'Polynomial division', 'Dividing polynomials by long or synthetic division to find a quotient and remainder.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_706efd3fab46a0', (SELECT id FROM concepts WHERE slug = 'polynomial-division'));

-- Lesson: end-behavior-turning-points
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c0d19e0bdda839', 'end-behavior-turning-points', 'End behavior and turning points', 'Predict the end behavior of a polynomial from its degree and leading coefficient, bound the number of turning points, and identify local maxima and minima.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4c73cf50771088', 'les_c0d19e0bdda839', 1, 'Determine end behavior from the leading term.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dca6da2d5f51a4', 'les_c0d19e0bdda839', 2, 'State that a degree-n polynomial has at most n − 1 turning points and at most n real zeros.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9beccbb5025c61', 'les_c0d19e0bdda839', 3, 'Identify relative maxima and minima and intervals of increase and decrease from a graph.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c73cf50771088', 'les_c0d19e0bdda839', 'learn', 1, 'definition', '{"term":"End behavior","body":"For large $|x|$, the leading term $a_n x^n$ dominates. Even degree: both ends point the same way (up if $a_n > 0$, down if $a_n < 0$). Odd degree: the ends point opposite ways (down-left, up-right if $a_n > 0$; reversed if $a_n < 0$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dca6da2d5f51a4', 'les_c0d19e0bdda839', 'learn', 2, 'definition', '{"term":"Turning points","body":"A degree-$n$ polynomial has at most $n - 1$ turning points (relative maxima or minima) and at most $n$ real zeros."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9beccbb5025c61', 'les_c0d19e0bdda839', 'learn', 3, 'worked_example', '{"title":"Describe $f(x) = -2x^5 + 7x^3 - x + 4$","steps":[{"latex":"\\text{leading term } -2x^5","explanation":"Odd degree, negative coefficient."},{"latex":"x \\to -\\infty: f \\to +\\infty;\\quad x \\to +\\infty: f \\to -\\infty","explanation":"Up on the left, down on the right."},{"latex":"\\text{at most 4 turning points, at most 5 real zeros}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8dbe32327c0394', 'les_c0d19e0bdda839', 'experiment', 4, 'activity', '{"activity":"polynomial-zeros","title":"Change degree and sign","params":{"a":-0.2,"r1":-4,"m1":1,"r2":0,"m2":1,"r3":3,"m3":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ec8ef4c91780d2', 'les_c0d19e0bdda839', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"The degree readout and end-behavior arrows update as you change multiplicities. Find a setting with degree 4 and only 1 turning point. (A degree-4 polynomial can have 1 or 3 turning points, never 2.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d272d90c32baeb', 'les_c0d19e0bdda839', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"End behavior tells you how a model behaves for extreme inputs, which is when polynomial models usually break down, a warning sign for extrapolation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4c73cf50771088', 'les_c0d19e0bdda839', 1, 'practice', 'multiple_choice', 1, 'What is the end behavior of $f(x) = 3x^4 - x$?', '{"choices":["Both ends up","Both ends down","Left down, right up","Left up, right down"],"answer":0}', '[]', 'Even degree, positive leading coefficient.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dca6da2d5f51a4', 'les_c0d19e0bdda839', 2, 'practice', 'multiple_choice', 2, 'What is the end behavior of $f(x) = -x^3 + 2x^2$?', '{"choices":["Both ends up","Both ends down","Left down, right up","Left up, right down"],"answer":3}', '[]', 'Odd degree, negative leading coefficient.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9beccbb5025c61', 'les_c0d19e0bdda839', 3, 'practice', 'numeric', 2, 'What is the maximum number of turning points of a degree-6 polynomial?', '{"answer":5}', '[]', '$n - 1 = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8dbe32327c0394', 'les_c0d19e0bdda839', 4, 'practice', 'multiple_choice', 2, 'A polynomial graph has 3 turning points. What is the smallest possible degree?', '{"choices":["2","3","4","5"],"answer":2}', '["Turning points ≤ n − 1."]', '$n - 1 \ge 3$, so $n \ge 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ec8ef4c91780d2', 'les_c0d19e0bdda839', 5, 'review', 'multiple_choice', 3, 'A graph rises on both ends and has 3 turning points. Which degree is possible?', '{"choices":["3","4","5","7"],"answer":1}', '["Both ends up: even degree."]', 'Even degree with at least 4: degree 4 (or 6, 8, …).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_388c63c9c58169', 'subj_math', 'polynomial-functions', 'Polynomial functions', 'Functions built from sums of powers of x with whole-number exponents.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c0d19e0bdda839', (SELECT id FROM concepts WHERE slug = 'polynomial-functions'));

-- Lesson: exponential-log-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_55d9e9697566b7', 'exponential-log-equations', 'Solving exponential and logarithmic equations', 'Solve exponential equations with common bases or logarithms, solve logarithmic equations by exponentiating, and check domain restrictions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_640440792fd598', 'les_55d9e9697566b7', 1, 'Solve exponential equations by rewriting with a common base or by taking logarithms.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_469ae3db0d254d', 'les_55d9e9697566b7', 2, 'Solve logarithmic equations by rewriting in exponential form.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d93fa49204430d', 'les_55d9e9697566b7', 3, 'Reject extraneous solutions that make a log argument nonpositive, and solve doubling-time problems.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_640440792fd598', 'les_55d9e9697566b7', 'learn', 1, 'text', '{"body":"To solve for an unknown exponent, take a logarithm of both sides; the power rule brings the exponent down. To solve for something inside a logarithm, rewrite in exponential form."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_469ae3db0d254d', 'les_55d9e9697566b7', 'learn', 2, 'worked_example', '{"title":"Solve $8^{x + 1} = 32$","steps":[{"latex":"2^{3(x + 1)} = 2^5","explanation":"Common base 2."},{"latex":"3x + 3 = 5 \\Rightarrow x = \\tfrac{2}{3}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d93fa49204430d', 'les_55d9e9697566b7', 'learn', 3, 'worked_example', '{"title":"Solve $5 \\cdot 3^{x} = 80$","steps":[{"latex":"3^x = 16","explanation":"Isolate the power."},{"latex":"x = \\frac{\\ln 16}{\\ln 3} \\approx 2.524","explanation":"Take ln of both sides."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f4bdcbd62b3ad1', 'les_55d9e9697566b7', 'learn', 4, 'worked_example', '{"title":"How long does money take to double at 6% compounded continuously?","steps":[{"latex":"2 = e^{0.06t}","explanation":""},{"latex":"t = \\frac{\\ln 2}{0.06} \\approx 11.55 \\text{ years}","explanation":"The ''rule of 70'': about 70 ÷ 6."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f0b7e3296eabec', 'les_55d9e9697566b7', 'learn', 5, 'worked_example', '{"title":"Solve $\\log_2 x + \\log_2(x - 2) = 3$","steps":[{"latex":"\\log_2[x(x - 2)] = 3 \\Rightarrow x^2 - 2x = 8","explanation":""},{"latex":"(x - 4)(x + 2) = 0","explanation":""},{"latex":"x = 4","explanation":"x = −2 is extraneous: log₂(−2) is undefined."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_75a175166e582b', 'les_55d9e9697566b7', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Carbon dating, half-life calculations, how long until a loan doubles, and when a population reaches a target all require solving for an exponent."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_640440792fd598', 'les_55d9e9697566b7', 1, 'practice', 'numeric', 1, 'Solve $2^{x} = 64$.', '{"answer":6}', '[]', '6.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_469ae3db0d254d', 'les_55d9e9697566b7', 2, 'practice', 'numeric', 2, 'Solve $9^{x} = 27$. Enter a decimal or fraction.', '{"answer":1.5}', '["$3^{2x} = 3^3$."]', '$x = 1.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d93fa49204430d', 'les_55d9e9697566b7', 3, 'practice', 'numeric', 2, 'Solve $4e^{x} = 20$ to three decimals.', '{"answer":1.609,"tolerance":0.0006}', '[]', '$x = \ln 5 \approx 1.609$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f4bdcbd62b3ad1', 'les_55d9e9697566b7', 4, 'practice', 'numeric', 2, 'Solve $\log_3(2x + 1) = 4$.', '{"answer":40}', '["$2x + 1 = 81$."]', '$x = 40$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f0b7e3296eabec', 'les_55d9e9697566b7', 5, 'review', 'numeric', 3, 'A sample decays as $A = 500e^{-0.0231t}$. When is it 250 (its half-life)? Round to the nearest tenth.', '{"answer":30,"tolerance":0.06}', '["$t = \\ln 2 / 0.0231$."]', '$0.6931 / 0.0231 \approx 30.0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_75a175166e582b', 'les_55d9e9697566b7', 6, 'review', 'short_text', 3, 'Solve $\log(x) + \log(x - 3) = 1$. Enter the valid solution.', '{"accept":["5","x=5"]}', '["$x^2 - 3x = 10$."]', '$(x - 5)(x + 2) = 0$; $x = -2$ is extraneous, so $x = 5$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_98ef8be0f3a311', 'subj_math', 'logarithms', 'Logarithms', 'Exponents: log_b x is the power of b that gives x.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_55d9e9697566b7', (SELECT id FROM concepts WHERE slug = 'logarithms'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_55d9e9697566b7', (SELECT id FROM formulas WHERE slug = 'log-properties'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_55d9e9697566b7', (SELECT id FROM formulas WHERE slug = 'continuous-growth'), 2);

-- Lesson: finding-polynomial-zeros
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_13d2ea33ad8fa3', 'finding-polynomial-zeros', 'Finding zeros of polynomials', 'Use the Rational Root Theorem to list candidates, test them, reduce the polynomial, and finish with factoring or the quadratic formula.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_68c95d201f3aa0', 'les_13d2ea33ad8fa3', 1, 'List possible rational zeros with the Rational Root Theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b7653cd6796c75', 'les_13d2ea33ad8fa3', 2, 'Find all zeros, real and complex, by testing, dividing and solving the remaining quadratic.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_42198621adb8ff', 'les_13d2ea33ad8fa3', 3, 'Use graphs to choose which candidates to test.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_68c95d201f3aa0', 'les_13d2ea33ad8fa3', 'learn', 1, 'definition', '{"term":"Rational Root Theorem","body":"If $P(x)$ has integer coefficients, every rational zero has the form $\\frac{p}{q}$, where $p$ divides the constant term and $q$ divides the leading coefficient."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b7653cd6796c75', 'les_13d2ea33ad8fa3', 'learn', 2, 'worked_example', '{"title":"Find all zeros of $P(x) = 2x^3 - 3x^2 - 8x - 3$","steps":[{"latex":"\\pm 1, \\pm 3, \\pm \\tfrac{1}{2}, \\pm \\tfrac{3}{2}","explanation":"p divides 3, q divides 2."},{"latex":"P(3) = 54 - 27 - 24 - 3 = 0","explanation":"3 is a zero."},{"latex":"P(x) = (x - 3)(2x^2 + 3x + 1) = (x - 3)(2x + 1)(x + 1)","explanation":"Divide, then factor."},{"latex":"x = 3,\\ -\\tfrac{1}{2},\\ -1","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_42198621adb8ff', 'les_13d2ea33ad8fa3', 'learn', 3, 'worked_example', '{"title":"Find all zeros of $x^3 - x^2 + 4x - 4$","steps":[{"latex":"x^2(x - 1) + 4(x - 1) = (x - 1)(x^2 + 4)","explanation":"Grouping works here."},{"latex":"x = 1,\\ \\pm 2i","explanation":"x² = −4 gives complex zeros."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb7ddd0a462a8a', 'les_13d2ea33ad8fa3', 'learn', 4, 'callout', '{"tone":"tip","title":"Let the graph narrow the list","body":"A quick graph shows roughly where the real zeros are, so you test only the nearby candidates."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_130da2a302c36a', 'les_13d2ea33ad8fa3', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Solving for when a box reaches a target volume, or when a polynomial cost model breaks even, means finding polynomial zeros. Software uses numerical methods, but exact zeros come from these theorems."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_68c95d201f3aa0', 'les_13d2ea33ad8fa3', 1, 'practice', 'multiple_choice', 1, 'Which is NOT a possible rational zero of $3x^3 + x - 4$?', '{"choices":["1","4/3","3","−1/3"],"answer":2}', '["p divides 4, q divides 3."]', 'Candidates are $\pm 1, \pm 2, \pm 4, \pm \frac{1}{3}, \pm \frac{2}{3}, \pm \frac{4}{3}$. 3 isn''t on the list because 3 doesn''t divide 4.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b7653cd6796c75', 'les_13d2ea33ad8fa3', 2, 'practice', 'short_text', 2, 'Find all zeros of $x^3 - 7x - 6$, smallest first.', '{"accept":["-2,-1,3"]}', '["Try x = −1."]', '$(x + 1)(x^2 - x - 6) = (x + 1)(x - 3)(x + 2)$: $-2, -1, 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_42198621adb8ff', 'les_13d2ea33ad8fa3', 3, 'practice', 'short_text', 2, 'Find all zeros of $x^3 + 9x$. Enter like 0,±3i.', '{"accept":["0,±3i","0,3i,-3i","-3i,0,3i"]}', '[]', '$x(x^2 + 9)$: $0, \pm 3i$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cb7ddd0a462a8a', 'les_13d2ea33ad8fa3', 4, 'review', 'short_text', 3, 'Find all real zeros of $2x^3 + x^2 - 13x + 6$, smallest first.', '{"accept":["-3,1/2,2"]}', '["Try x = 2.","Then 2x² + 5x − 3."]', '$(x - 2)(2x^2 + 5x - 3) = (x - 2)(2x - 1)(x + 3)$: $-3, \frac{1}{2}, 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_388c63c9c58169', 'subj_math', 'polynomial-functions', 'Polynomial functions', 'Functions built from sums of powers of x with whole-number exponents.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_13d2ea33ad8fa3', (SELECT id FROM concepts WHERE slug = 'polynomial-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_13d2ea33ad8fa3', (SELECT id FROM formulas WHERE slug = 'quadratic-formula'), 1);

-- Lesson: fundamental-theorem-algebra
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_001fd2991f0a8b', 'fundamental-theorem-algebra', 'The Fundamental Theorem of Algebra', 'Use the Fundamental Theorem of Algebra and the Conjugate Root Theorem to count zeros, find all complex zeros, and write polynomials from given zeros.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_afd2c16696218a', 'les_001fd2991f0a8b', 1, 'State that a degree-n polynomial has exactly n complex zeros counting multiplicity.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a25dd4a8499cdb', 'les_001fd2991f0a8b', 2, 'Apply the Complex Conjugate Root Theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7d760566a09caf', 'les_001fd2991f0a8b', 3, 'Write a polynomial with real coefficients from given real and complex zeros.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_afd2c16696218a', 'les_001fd2991f0a8b', 'learn', 1, 'definition', '{"term":"Fundamental Theorem of Algebra","body":"Every polynomial of degree $n \\ge 1$ with complex coefficients has at least one complex zero. As a consequence it has exactly $n$ zeros, counting multiplicity, and factors completely into linear factors over the complex numbers."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a25dd4a8499cdb', 'les_001fd2991f0a8b', 'learn', 2, 'definition', '{"term":"Conjugate Root Theorem","body":"If a polynomial has real coefficients and $a + bi$ is a zero, then $a - bi$ is also a zero. Complex zeros come in pairs, so an odd-degree real polynomial has at least one real zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7d760566a09caf', 'les_001fd2991f0a8b', 'learn', 3, 'worked_example', '{"title":"Write a cubic with real coefficients and zeros 2 and $1 + 3i$","steps":[{"latex":"\\text{zeros: } 2,\\ 1 + 3i,\\ 1 - 3i","explanation":"Include the conjugate."},{"latex":"(x - (1 + 3i))(x - (1 - 3i)) = (x - 1)^2 + 9 = x^2 - 2x + 10","explanation":""},{"latex":"(x - 2)(x^2 - 2x + 10) = x^3 - 4x^2 + 14x - 20","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f1d5785c23ee4d', 'les_001fd2991f0a8b', 'experiment', 4, 'activity', '{"activity":"polynomial-zeros","title":"Real zeros you can see","params":{"a":0.2,"r1":-2,"m1":1,"r2":1,"m2":1,"r3":3,"m3":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf0750e5028578', 'les_001fd2991f0a8b', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"A cubic with three real zeros crosses the axis three times. If two of its zeros were complex, the graph would cross only once. You can''t place complex zeros on this real graph, which is exactly why they''re \"invisible\" on it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96664ad479fe3f', 'les_001fd2991f0a8b', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Control engineers find the zeros (poles) of characteristic polynomials to check whether a system is stable; complex pairs mean oscillation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_afd2c16696218a', 'les_001fd2991f0a8b', 1, 'practice', 'numeric', 1, 'How many complex zeros, counting multiplicity, does $x^7 - 3x + 1$ have?', '{"answer":7}', '[]', 'Degree 7: seven zeros.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a25dd4a8499cdb', 'les_001fd2991f0a8b', 2, 'practice', 'multiple_choice', 2, 'A real polynomial has zeros $4$ and $2 - i$. Which must also be a zero?', '{"choices":["$-4$","$2 + i$","$-2 + i$","$i$"],"answer":1}', '[]', 'The conjugate $2 + i$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7d760566a09caf', 'les_001fd2991f0a8b', 3, 'practice', 'short_text', 2, 'Write the quadratic with real coefficients and zero $3i$, leading coefficient 1.', '{"accept":["x^2+9"]}', '[]', '$(x - 3i)(x + 3i) = x^2 + 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f1d5785c23ee4d', 'les_001fd2991f0a8b', 4, 'review', 'multiple_choice', 3, 'Can a real cubic have exactly two real zeros (counted without multiplicity) and one non-real zero?', '{"choices":["Yes","No, non-real zeros come in conjugate pairs","Only if it has a double zero","Only if the leading coefficient is negative"],"answer":1}', '[]', 'One non-real zero would force its conjugate, making 4 zeros: impossible for degree 3.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_388c63c9c58169', 'subj_math', 'polynomial-functions', 'Polynomial functions', 'Functions built from sums of powers of x with whole-number exponents.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_001fd2991f0a8b', (SELECT id FROM concepts WHERE slug = 'polynomial-functions'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d7a3ca35193c15', 'subj_math', 'complex-numbers', 'Complex numbers', 'Numbers a + bi with real a and b, where i² = −1.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_001fd2991f0a8b', (SELECT id FROM concepts WHERE slug = 'complex-numbers'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_001fd2991f0a8b', (SELECT id FROM formulas WHERE slug = 'complex-numbers'), 1);

-- Lesson: geometric-series
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_de0782fbc4a24b', 'geometric-series', 'Geometric sequences and series', 'Find terms of geometric sequences and derive and use the formula for the sum of a finite geometric series, including loan and savings problems.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b5fe9ff8a387b2', 'les_de0782fbc4a24b', 1, 'Write rules for geometric sequences.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_017cd23b95b060', 'les_de0782fbc4a24b', 2, 'Derive S_n = a₁(1 − rⁿ)/(1 − r) by multiplying and subtracting.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ee37d6126088b1', 'les_de0782fbc4a24b', 3, 'Apply geometric series to savings, loans and repeated doubling.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5fe9ff8a387b2', 'les_de0782fbc4a24b', 'learn', 1, 'text', '{"body":"Write $S_n = a_1 + a_1 r + \\cdots + a_1 r^{n-1}$, then multiply by $r$: $rS_n = a_1 r + \\cdots + a_1 r^n$. Subtracting, almost everything cancels: $S_n - rS_n = a_1 - a_1 r^n$. So for $r \\ne 1$:"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_017cd23b95b060', 'les_de0782fbc4a24b', 'learn', 2, 'definition', '{"term":"Geometric series sum","body":"$S_n = a_1 \\dfrac{1 - r^n}{1 - r}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ee37d6126088b1', 'les_de0782fbc4a24b', 'learn', 3, 'worked_example', '{"title":"Find $3 + 6 + 12 + \\cdots$ to 10 terms","steps":[{"latex":"S_{10} = 3 \\cdot \\frac{1 - 2^{10}}{1 - 2} = 3 \\cdot 1023 = 3069","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26e4a750ddf9a0', 'les_de0782fbc4a24b', 'learn', 4, 'worked_example', '{"title":"You save 100 dollars the first month and 5% more each month after. How much in total after 12 months?","steps":[{"latex":"S_{12} = 100 \\cdot \\frac{1 - 1.05^{12}}{1 - 1.05}","explanation":""},{"latex":"\\approx 100 \\cdot 15.917 \\approx 1591.71","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb87e36615d909', 'les_de0782fbc4a24b', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Loan payment formulas, annuities, the total number of ancestors over generations and chain-letter growth all sum geometric series."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b5fe9ff8a387b2', 'les_de0782fbc4a24b', 1, 'practice', 'numeric', 1, 'Find the 6th term of 2, 6, 18, …', '{"answer":486}', '["$2 \\cdot 3^5$."]', '486.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_017cd23b95b060', 'les_de0782fbc4a24b', 2, 'practice', 'numeric', 2, 'Find $1 + 2 + 4 + \cdots + 512$.', '{"answer":1023}', '["10 terms, r = 2."]', '$\frac{1 - 2^{10}}{1 - 2} = 1023$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ee37d6126088b1', 'les_de0782fbc4a24b', 3, 'practice', 'numeric', 2, 'Find the sum of the first 5 terms of 81, 27, 9, …', '{"answer":121}', '["$r = \\frac{1}{3}$."]', '$81 + 27 + 9 + 3 + 1 = 121$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_26e4a750ddf9a0', 'les_de0782fbc4a24b', 4, 'review', 'numeric', 3, 'A gift of 1 cent on day 1, doubling each day: what is the total after 20 days, in dollars?', '{"answer":10485.75,"tolerance":0.01,"unit":"dollars"}', '["$0.01(2^{20} - 1)$."]', '$0.01 \cdot 1{,}048{,}575 = 10{,}485.75$ dollars.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_de0782fbc4a24b', (SELECT id FROM concepts WHERE slug = 'geometric-sequences'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8c45d090913a21', 'subj_math', 'series', 'Series', 'The sum of the terms of a sequence.');
