-- Lesson: infinite-geometric-series
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a40992aba6e6df', 'infinite-geometric-series', 'Infinite geometric series', 'Decide when an infinite geometric series converges, find its sum, and use it to write repeating decimals as fractions.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3311f23c11e3f4', 'les_a40992aba6e6df', 1, 'Explain convergence through partial sums.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a45750d440fb40', 'les_a40992aba6e6df', 2, 'Use S = a₁/(1 − r) when |r| < 1.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e6b3d54e0db797', 'les_a40992aba6e6df', 3, 'Convert repeating decimals to fractions and solve applied problems.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3311f23c11e3f4', 'les_a40992aba6e6df', 'learn', 1, 'text', '{"body":"Walk half the remaining distance to a wall, again and again: $\\frac{1}{2} + \\frac{1}{4} + \\frac{1}{8} + \\cdots$. The partial sums are $0.5, 0.75, 0.875, \\dots$, getting as close to 1 as you like. An infinite sum can have a finite value."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a45750d440fb40', 'les_a40992aba6e6df', 'learn', 2, 'definition', '{"term":"Sum of an infinite geometric series","body":"If $|r| < 1$, then $r^n \\to 0$, so $S_n = a_1\\frac{1 - r^n}{1 - r}$ approaches $S = \\frac{a_1}{1 - r}$. If $|r| \\ge 1$, the series diverges (has no sum)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e6b3d54e0db797', 'les_a40992aba6e6df', 'learn', 3, 'worked_example', '{"title":"Find $12 - 6 + 3 - \\tfrac{3}{2} + \\cdots$","steps":[{"latex":"r = -\\tfrac{1}{2}","explanation":"|r| < 1: converges."},{"latex":"S = \\frac{12}{1 + \\tfrac{1}{2}} = 8","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6be2637dafd696', 'les_a40992aba6e6df', 'learn', 4, 'worked_example', '{"title":"Write $0.\\overline{27}$ as a fraction","steps":[{"latex":"0.27 + 0.0027 + \\cdots,\\ r = 0.01","explanation":""},{"latex":"S = \\frac{0.27}{0.99} = \\frac{27}{99} = \\frac{3}{11}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a1d4ac27e42cea', 'les_a40992aba6e6df', 'learn', 5, 'callout', '{"tone":"warning","title":"Check |r| first","body":"The formula gives nonsense for divergent series: $1 + 2 + 4 + \\cdots$ would \"sum\" to $\\frac{1}{1 - 2} = -1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c03cb6d1f4f662', 'les_a40992aba6e6df', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"The total distance of a bouncing ball, the long-run effect of repeated drug doses, and the \"multiplier effect\" in economics are infinite geometric series."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3311f23c11e3f4', 'les_a40992aba6e6df', 1, 'practice', 'numeric', 1, 'Find $\frac{1}{3} + \frac{1}{9} + \frac{1}{27} + \cdots$. Enter a decimal or fraction.', '{"answer":0.5}', '["$a_1 = \\frac{1}{3}$, $r = \\frac{1}{3}$."]', '$\frac{1/3}{2/3} = \frac{1}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a45750d440fb40', 'les_a40992aba6e6df', 2, 'practice', 'multiple_choice', 2, 'Which series converges?', '{"choices":["$2 + 4 + 8 + \\cdots$","$5 - 5 + 5 - \\cdots$","$9 + 3 + 1 + \\cdots$","$1 + 1.1 + 1.21 + \\cdots$"],"answer":2}', '["Find |r|."]', '$r = \frac{1}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e6b3d54e0db797', 'les_a40992aba6e6df', 3, 'practice', 'short_text', 2, 'Write $0.\overline{4}$ as a fraction.', '{"accept":["4/9"]}', '[]', '$\frac{0.4}{0.9} = \frac{4}{9}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6be2637dafd696', 'les_a40992aba6e6df', 4, 'review', 'numeric', 3, 'A ball dropped from 10 m rebounds to 60% of its height each time. What total vertical distance does it travel?', '{"answer":40,"unit":"m"}', '["Down 10, then up and down 6 + 3.6 + …","$10 + 2 \\cdot \\frac{6}{1 - 0.6}$."]', '$10 + 2 \cdot 15 = 40$ m.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8c45d090913a21', 'subj_math', 'series', 'Series', 'The sum of the terms of a sequence.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a40992aba6e6df', (SELECT id FROM concepts WHERE slug = 'series'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a40992aba6e6df', (SELECT id FROM formulas WHERE slug = 'series-sums'), 1);

-- Lesson: inverse-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3b74e028914870', 'inverse-functions', 'Inverse functions', 'Find inverses by swapping x and y, verify them by composition, graph them as reflections across y = x, and restrict domains when a function isn''t one-to-one.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f9e859e010da09', 'les_3b74e028914870', 1, 'Find the inverse of a function algebraically.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e77c78af104305', 'les_3b74e028914870', 2, 'Verify inverses with f(f⁻¹(x)) = x and f⁻¹(f(x)) = x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b4768bad37d758', 'les_3b74e028914870', 3, 'Use the horizontal line test and restrict a domain so a function has an inverse.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9e859e010da09', 'les_3b74e028914870', 'learn', 1, 'definition', '{"term":"Inverse function","body":"$f^{-1}$ undoes $f$: if $f(a) = b$ then $f^{-1}(b) = a$. The inverse swaps inputs and outputs, so its graph is the reflection of $f$''s graph across $y = x$. (Note $f^{-1}(x) \\ne \\frac{1}{f(x)}$.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e77c78af104305', 'les_3b74e028914870', 'learn', 2, 'worked_example', '{"title":"Find the inverse of $f(x) = \\frac{2x - 5}{3}$","steps":[{"latex":"x = \\tfrac{2y - 5}{3}","explanation":"Write y = f(x), then swap x and y."},{"latex":"3x = 2y - 5 \\Rightarrow y = \\tfrac{3x + 5}{2}","explanation":"Solve for y."},{"latex":"f^{-1}(x) = \\tfrac{3x + 5}{2}","explanation":""}],"check":"Check: $f(f^{-1}(x)) = \\frac{2 \\cdot \\frac{3x + 5}{2} - 5}{3} = \\frac{3x}{3} = x$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b4768bad37d758', 'les_3b74e028914870', 'learn', 3, 'definition', '{"term":"One-to-one","body":"A function has an inverse function only if it is one-to-one: each output comes from exactly one input. Graphically, every horizontal line crosses it at most once (the horizontal line test)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_abaa1774613ee0', 'les_3b74e028914870', 'learn', 4, 'worked_example', '{"title":"$f(x) = x^2$ fails the horizontal line test. Restrict it and find an inverse.","steps":[{"latex":"\\text{restrict to } x \\ge 0","explanation":"Keep the right half of the parabola."},{"latex":"f^{-1}(x) = \\sqrt{x}","explanation":"Domain x ≥ 0."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c393a8a1cb12cb', 'les_3b74e028914870', 'experiment', 5, 'activity', '{"activity":"exp-log","title":"A function and its inverse","params":{"b":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c5df81cad6dbcb', 'les_3b74e028914870', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"$2^x$ and $\\log_2 x$ are inverses. The matching points readout shows $(x, y)$ on one and $(y, x)$ on the other, mirror images across the dashed line $y = x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a2d8f524a2621f', 'les_3b74e028914870', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Converting Celsius to Fahrenheit and back, decrypting a coded message, and reading a value off a calibration curve all use inverse functions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f9e859e010da09', 'les_3b74e028914870', 1, 'practice', 'short_text', 1, 'Find $f^{-1}(x)$ for $f(x) = x + 9$.', '{"accept":["x-9"]}', '[]', '$x - 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e77c78af104305', 'les_3b74e028914870', 2, 'practice', 'short_text', 2, 'Find $f^{-1}(x)$ for $f(x) = 4x - 3$. Write it like (x+3)/4.', '{"accept":["(x+3)/4","x/4+3/4"]}', '[]', '$\frac{x + 3}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b4768bad37d758', 'les_3b74e028914870', 3, 'practice', 'numeric', 2, 'If $f(5) = 12$, what is $f^{-1}(12)$?', '{"answer":5}', '[]', '5.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_abaa1774613ee0', 'les_3b74e028914870', 4, 'practice', 'multiple_choice', 2, 'Which function has an inverse that is a function?', '{"choices":["$y = x^2$","$y = |x|$","$y = x^3$","$y = x^2 - 4$"],"answer":2}', '["Horizontal line test."]', '$x^3$ is one-to-one.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c393a8a1cb12cb', 'les_3b74e028914870', 5, 'review', 'short_text', 3, 'Find $f^{-1}(x)$ for $f(x) = \sqrt{x - 2}$, $x \ge 2$. Write it like x^2+2.', '{"accept":["x^2+2"]}', '["Swap and square."]', '$x = \sqrt{y - 2}$ gives $y = x^2 + 2$ for $x \ge 0$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3b74e028914870', 'subj_math', 'inverse-functions', 'Inverse functions', 'Functions that undo each other: f⁻¹(f(x)) = x.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3b74e028914870', (SELECT id FROM concepts WHERE slug = 'inverse-functions'));

-- Lesson: log-scales-modeling
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b30dc315ede8ce', 'log-scales-modeling', 'Logarithmic scales and modeling data', 'Work with decibels, pH and the Richter scale, and use logarithms to linearize exponential data and fit models.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e5989b3ebab887', 'les_b30dc315ede8ce', 1, 'Compute and compare values on logarithmic scales (decibels, pH, magnitude).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_114ef8b6362435', 'les_b30dc315ede8ce', 2, 'Explain why log scales compress huge ranges.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1ef90d04a3c1d6', 'les_b30dc315ede8ce', 3, 'Linearize exponential data by taking logarithms and find an exponential model.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e5989b3ebab887', 'les_b30dc315ede8ce', 'learn', 1, 'text', '{"body":"Sound intensity, acidity and earthquake energy span ranges of billions. A logarithmic scale replaces each value with its exponent, so each step of 1 means a multiplication by 10 (or another base)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_114ef8b6362435', 'les_b30dc315ede8ce', 'learn', 2, 'definition', '{"term":"Common scales","body":"Decibels: $L = 10\\log\\frac{I}{I_0}$. pH: $\\text{pH} = -\\log[\\text{H}^+]$. Richter-style magnitude: each whole unit is 10 times the measured amplitude (about 32 times the energy)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ef90d04a3c1d6', 'les_b30dc315ede8ce', 'learn', 3, 'worked_example', '{"title":"How many times more intense is a 90 dB sound than a 60 dB sound?","steps":[{"latex":"90 - 60 = 30 \\text{ dB} = 10\\log\\tfrac{I_1}{I_2}","explanation":""},{"latex":"\\tfrac{I_1}{I_2} = 10^3 = 1000","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_993d7b83c17928', 'les_b30dc315ede8ce', 'learn', 4, 'worked_example', '{"title":"Data: $(0, 3), (1, 6), (2, 12), (3, 24)$. Show it''s exponential with logs and find the model.","steps":[{"latex":"\\ln y: 1.099, 1.792, 2.485, 3.178","explanation":"Equal steps of 0.693: linear in x."},{"latex":"\\ln y = 1.099 + 0.693x \\Rightarrow y = e^{1.099}e^{0.693x} = 3 \\cdot 2^x","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4f318d3e333459', 'les_b30dc315ede8ce', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Scientists plot exponential data on log-scale (semi-log) graphs, where it appears as a straight line; this is how epidemic curves, Moore''s law and radioactive decay are often shown."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e5989b3ebab887', 'les_b30dc315ede8ce', 1, 'practice', 'numeric', 1, 'What is the pH of a solution with $[\text{H}^+] = 10^{-5}$?', '{"answer":5}', '[]', '5.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_114ef8b6362435', 'les_b30dc315ede8ce', 2, 'practice', 'numeric', 2, 'An earthquake of magnitude 7 has how many times the amplitude of a magnitude 5 quake?', '{"answer":100}', '[]', '$10^2 = 100$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1ef90d04a3c1d6', 'les_b30dc315ede8ce', 3, 'practice', 'numeric', 2, 'Find the decibel level of a sound with intensity $10^{8}$ times the threshold.', '{"answer":80,"unit":"dB"}', '[]', '$10 \cdot 8 = 80$ dB.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_993d7b83c17928', 'les_b30dc315ede8ce', 4, 'review', 'numeric', 3, 'Lemon juice has pH 2 and milk pH 6.5. How many times greater is lemon juice''s $[\text{H}^+]$? Round to the nearest whole number.', '{"answer":31623,"tolerance":1}', '["$10^{4.5}$."]', '$10^{4.5} \approx 31{,}623$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_98ef8be0f3a311', 'subj_math', 'logarithms', 'Logarithms', 'Exponents: log_b x is the power of b that gives x.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b30dc315ede8ce', (SELECT id FROM concepts WHERE slug = 'logarithms'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b30dc315ede8ce', (SELECT id FROM formulas WHERE slug = 'log-properties'), 1);

-- Lesson: logarithms-as-inverses
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_89b5b24c69b23c', 'logarithms-as-inverses', 'Logarithms as inverses', 'Define logarithms as exponents, convert between exponential and logarithmic form, evaluate logs, and graph log functions as inverses of exponentials.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dedca1f0779114', 'les_89b5b24c69b23c', 1, 'Convert between y = log_b x and b^y = x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7c0c192b3242f9', 'les_89b5b24c69b23c', 2, 'Evaluate logarithms, including common (log) and natural (ln) logs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c49e6dde52614e', 'les_89b5b24c69b23c', 3, 'Graph logarithmic functions and state their domain, range and asymptote.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dedca1f0779114', 'les_89b5b24c69b23c', 'learn', 1, 'definition', '{"term":"Logarithm","body":"For $b > 0$, $b \\ne 1$ and $x > 0$: $\\log_b x = y$ means $b^y = x$. A logarithm is an exponent: $\\log_2 8 = 3$ because $2^3 = 8$. $\\log x$ means $\\log_{10} x$ and $\\ln x$ means $\\log_e x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c0c192b3242f9', 'les_89b5b24c69b23c', 'learn', 2, 'worked_example', '{"title":"Evaluate $\\log_3 81$, $\\log_5 \\tfrac{1}{25}$ and $\\log 0.001$","steps":[{"latex":"3^4 = 81 \\Rightarrow 4","explanation":""},{"latex":"5^{-2} = \\tfrac{1}{25} \\Rightarrow -2","explanation":""},{"latex":"10^{-3} = 0.001 \\Rightarrow -3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c49e6dde52614e', 'les_89b5b24c69b23c', 'learn', 3, 'text', '{"body":"Because $\\log_b x$ and $b^x$ are inverses, $\\log_b(b^x) = x$ and $b^{\\log_b x} = x$. The graph of $y = \\log_b x$ is the reflection of $y = b^x$ across $y = x$: domain $x > 0$, range all reals, vertical asymptote $x = 0$, and it passes through $(1, 0)$ and $(b, 1)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0025157de81d83', 'les_89b5b24c69b23c', 'experiment', 4, 'activity', '{"activity":"exp-log","title":"Exponential and log as mirror images","params":{"b":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f44f52f62a742a', 'les_89b5b24c69b23c', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"With base 3, move the point to $x = 2$: the exponential gives $(2, 9)$ and the log gives $(9, 2)$, so $\\log_3 9 = 2$. Try a base less than 1: what happens to both graphs?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e0ebb44796bf02', 'les_89b5b24c69b23c', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Logarithms measure things that span huge ranges: the Richter scale, decibels, pH, and the number of digits in a number ($\\lfloor\\log n\\rfloor + 1$)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dedca1f0779114', 'les_89b5b24c69b23c', 1, 'practice', 'numeric', 1, 'Evaluate $\log_2 32$.', '{"answer":5}', '[]', '$2^5 = 32$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c0c192b3242f9', 'les_89b5b24c69b23c', 2, 'practice', 'numeric', 1, 'Evaluate $\log 10{,}000$.', '{"answer":4}', '[]', '4.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c49e6dde52614e', 'les_89b5b24c69b23c', 3, 'practice', 'numeric', 2, 'Evaluate $\log_4 2$. Enter a decimal.', '{"answer":0.5}', '["$4^{1/2} = 2$."]', '$0.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0025157de81d83', 'les_89b5b24c69b23c', 4, 'practice', 'multiple_choice', 2, 'Which is the exponential form of $\log_6 y = 3$?', '{"choices":["$y^3 = 6$","$6^3 = y$","$3^6 = y$","$6^y = 3$"],"answer":1}', '[]', '$6^3 = y$, so $y = 216$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f44f52f62a742a', 'les_89b5b24c69b23c', 5, 'review', 'numeric', 3, 'Evaluate $\ln(e^{4})$.', '{"answer":4}', '[]', 'Inverse functions: 4.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_98ef8be0f3a311', 'subj_math', 'logarithms', 'Logarithms', 'Exponents: log_b x is the power of b that gives x.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_89b5b24c69b23c', (SELECT id FROM concepts WHERE slug = 'logarithms'));
