-- Lesson: margin-of-error
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3a420a076cbe34', 'margin-of-error', 'Margin of error', 'Use simulation and the normal model to understand sampling variability, compute and interpret a margin of error for a proportion, and see how sample size affects it.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eab6456438ce67', 'les_3a420a076cbe34', 1, 'Explain sampling variability with simulation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_182322b1d256c4', 'les_3a420a076cbe34', 2, 'Compute a 95% margin of error for a sample proportion.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dbb3442cf3ca59', 'les_3a420a076cbe34', 3, 'Interpret a confidence interval and explain how sample size affects precision.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eab6456438ce67', 'les_3a420a076cbe34', 'learn', 1, 'text', '{"body":"Two random samples from the same population almost never give exactly the same result. If you took many samples, the sample proportions would cluster around the true value in an approximately normal shape. The margin of error describes how wide that cluster is."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_182322b1d256c4', 'les_3a420a076cbe34', 'learn', 2, 'definition', '{"term":"Margin of error (95%)","body":"For a random sample of size $n$ with proportion $\\hat{p}$: $\\text{ME} \\approx 1.96\\sqrt{\\frac{\\hat{p}(1 - \\hat{p})}{n}}$. A quick upper bound is $\\frac{1}{\\sqrt{n}}$. The interval $\\hat{p} \\pm \\text{ME}$ is a 95% confidence interval."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dbb3442cf3ca59', 'les_3a420a076cbe34', 'learn', 3, 'worked_example', '{"title":"A random sample of 400 students finds 62% like the new schedule. Find the margin of error.","steps":[{"latex":"1.96\\sqrt{\\frac{0.62 \\cdot 0.38}{400}} \\approx 1.96(0.0243) \\approx 0.048","explanation":""},{"latex":"62\\% \\pm 4.8\\% \\Rightarrow (57.2\\%, 66.8\\%)","explanation":""}],"check":"Interpretation: we''re 95% confident the true proportion of all students is between 57.2% and 66.8%."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2da1cc9a70bb8f', 'les_3a420a076cbe34', 'experiment', 4, 'activity', '{"activity":"normal-distribution","title":"About 95% within 1.96 standard deviations","params":{"mu":0,"sigma":1,"lo":-1.96,"hi":1.96}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_399c71d742ce99', 'les_3a420a076cbe34', 'learn', 5, 'callout', '{"tone":"warning","title":"What 95% means","body":"It describes the method: about 95% of intervals made this way would contain the true value. It does not cover bias; a biased sample can be precisely wrong."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f3bbf4556d1392', 'les_3a420a076cbe34', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"News polls report \"plus or minus 3 points,\" which corresponds to about 1,000 people (since $1/\\sqrt{1000} \\approx 0.032$). Quadrupling the sample size only halves the margin."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eab6456438ce67', 'les_3a420a076cbe34', 1, 'practice', 'numeric', 2, 'Estimate the worst-case 95% margin of error for a sample of 2,500, as a percent.', '{"answer":2,"unit":"%"}', '["$1/\\sqrt{2500}$."]', '$0.02 = 2\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_182322b1d256c4', 'les_3a420a076cbe34', 2, 'practice', 'numeric', 2, 'A sample of 100 has $\hat{p} = 0.5$. Find the 95% margin of error, to three decimals.', '{"answer":0.098,"tolerance":0.0006}', '["$1.96\\sqrt{0.25/100}$."]', '$1.96 \cdot 0.05 = 0.098$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dbb3442cf3ca59', 'les_3a420a076cbe34', 3, 'practice', 'multiple_choice', 2, 'To cut the margin of error in half, the sample size must be…', '{"choices":["doubled","halved","quadrupled","unchanged"],"answer":2}', '["ME is proportional to $1/\\sqrt{n}$."]', '$\sqrt{4} = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2da1cc9a70bb8f', 'les_3a420a076cbe34', 4, 'review', 'multiple_choice', 3, 'A poll says 48% ± 3%. Which conclusion is best?', '{"choices":["Exactly 48% agree","The true value is likely between 45% and 51%","A majority definitely disagrees","The poll is wrong"],"answer":1}', '[]', 'The interval includes values on both sides of 50%.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_b8e00fdd472eae', 'subj_math', 'sampling', 'Sampling', 'Choosing part of a population to learn about the whole.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3a420a076cbe34', (SELECT id FROM concepts WHERE slug = 'sampling'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3a420a076cbe34', 'subj_math', 'margin-of-error', 'Margin of error', 'How far a sample estimate is likely to be from the true population value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3a420a076cbe34', (SELECT id FROM concepts WHERE slug = 'margin-of-error'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3a420a076cbe34', (SELECT id FROM formulas WHERE slug = 'margin-of-error'), 1);

-- Lesson: mathematical-induction
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_30ff004b56c489', 'mathematical-induction', 'Proof by mathematical induction', 'Prove statements about all positive integers with a base case and an inductive step, including sum formulas and divisibility.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_84be01477b106f', 'les_30ff004b56c489', 1, 'Describe the structure of an induction proof.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b2a196fb041449', 'les_30ff004b56c489', 2, 'Prove sum formulas such as 1 + 2 + … + n = n(n + 1)/2.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3592dd9f6a3c3a', 'les_30ff004b56c489', 3, 'Prove divisibility statements and identify flawed induction arguments.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_84be01477b106f', 'les_30ff004b56c489', 'learn', 1, 'text', '{"body":"Picture an infinite line of dominoes. If the first one falls, and each falling domino knocks over the next, then every domino falls. Induction proves infinitely many statements the same way."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b2a196fb041449', 'les_30ff004b56c489', 'learn', 2, 'definition', '{"term":"Induction","body":"To prove $P(n)$ for all integers $n \\ge 1$: (1) Base case: prove $P(1)$. (2) Inductive step: assume $P(k)$ is true for some $k \\ge 1$ (the inductive hypothesis) and prove $P(k + 1)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3592dd9f6a3c3a', 'les_30ff004b56c489', 'learn', 3, 'worked_example', '{"title":"Prove $1 + 3 + 5 + \\cdots + (2n - 1) = n^2$","steps":[{"latex":"n = 1: 1 = 1^2 ✓","explanation":"Base case."},{"latex":"\\text{Assume } 1 + 3 + \\cdots + (2k - 1) = k^2","explanation":"Inductive hypothesis."},{"latex":"k^2 + (2(k + 1) - 1) = k^2 + 2k + 1 = (k + 1)^2","explanation":"Add the next odd number. So P(k + 1) holds. ∎"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4242556f4f068', 'les_30ff004b56c489', 'learn', 4, 'worked_example', '{"title":"Prove $3^n - 1$ is divisible by 2 for all $n \\ge 1$","steps":[{"latex":"n = 1: 3 - 1 = 2 ✓","explanation":""},{"latex":"\\text{Assume } 3^k - 1 = 2m","explanation":""},{"latex":"3^{k+1} - 1 = 3 \\cdot 3^k - 1 = 3(2m + 1) - 1 = 6m + 2 = 2(3m + 1)","explanation":"Divisible by 2. ∎"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_79fa33d6d069c2', 'les_30ff004b56c489', 'learn', 5, 'callout', '{"tone":"warning","title":"Both steps are required","body":"Without a base case, you could \"prove\" $n = n + 1$ (the inductive step works, but no domino ever falls). Without the inductive step, checking examples proves nothing in general."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5285accb0df81b', 'les_30ff004b56c489', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Computer scientists prove loops and recursive algorithms correct by induction, and it underlies formulas used everywhere, such as the sums in sigma notation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_84be01477b106f', 'les_30ff004b56c489', 1, 'practice', 'multiple_choice', 1, 'What is the first step of an induction proof?', '{"choices":["Assume P(k)","Prove the base case","Prove P(k + 1)","Check many examples"],"answer":1}', '[]', 'Establish the base case.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b2a196fb041449', 'les_30ff004b56c489', 2, 'practice', 'multiple_choice', 2, 'In the inductive step, what do you assume?', '{"choices":["P(k + 1)","P(k) for some k","P(n) for all n","Nothing"],"answer":1}', '[]', 'The inductive hypothesis: P(k).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3592dd9f6a3c3a', 'les_30ff004b56c489', 3, 'practice', 'multiple_choice', 2, 'To prove $\sum_{i=1}^{n} i = \frac{n(n + 1)}{2}$, what must you show in the inductive step?', '{"choices":["$\\frac{k(k + 1)}{2} + (k + 1) = \\frac{(k + 1)(k + 2)}{2}$","$\\frac{k(k + 1)}{2} = \\frac{(k + 1)(k + 2)}{2}$","$1 = 1$","$k + 1 = k$"],"answer":0}', '[]', 'Add the next term to the assumed sum and simplify to the formula with $n = k + 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e4242556f4f068', 'les_30ff004b56c489', 4, 'review', 'multiple_choice', 3, 'A "proof" shows P(k) ⇒ P(k + 1) but never checks a base case. What''s true?', '{"choices":["The statement is proved","It''s not a proof; the statement may be false","It proves P(1) only","It proves P(0)"],"answer":1}', '[]', 'Without a starting point, nothing follows.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_e68231acf59543', 'subj_math', 'induction', 'Mathematical induction', 'Proving a statement for all integers n ≥ n₀ with a base case and an inductive step.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_30ff004b56c489', (SELECT id FROM concepts WHERE slug = 'induction'));

-- Lesson: matrix-operations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2fd8e2f269004d', 'matrix-operations', 'Matrix operations', 'Add, subtract and scale matrices, multiply matrices row-by-column, and recognize when products are defined and that order matters.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_45d949de1422d5', 'les_2fd8e2f269004d', 1, 'Identify a matrix''s dimensions and entries.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5a8e7f92614575', 'les_2fd8e2f269004d', 2, 'Add, subtract and multiply matrices by a scalar.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_868d52e2a5a3d7', 'les_2fd8e2f269004d', 3, 'Multiply matrices, check whether a product is defined, and show AB ≠ BA in general.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_45d949de1422d5', 'les_2fd8e2f269004d', 'learn', 1, 'definition', '{"term":"Matrix","body":"A rectangular array of numbers with $m$ rows and $n$ columns (an $m \\times n$ matrix). The entry in row $i$, column $j$ is $a_{ij}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5a8e7f92614575', 'les_2fd8e2f269004d', 'learn', 2, 'text', '{"body":"Add or subtract matrices of the same dimensions entry by entry. Multiplying by a scalar multiplies every entry. Matrix multiplication is different: the entry in row $i$, column $j$ of $AB$ is the dot product of row $i$ of $A$ with column $j$ of $B$. It''s defined only when $A$''s columns equal $B$''s rows: $(m \\times n)(n \\times p) = m \\times p$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_868d52e2a5a3d7', 'les_2fd8e2f269004d', 'learn', 3, 'worked_example', '{"title":"Multiply $\\begin{bmatrix} 1 & 2 \\\\ 3 & 4 \\end{bmatrix}\\begin{bmatrix} 5 & 0 \\\\ -1 & 2 \\end{bmatrix}$","steps":[{"latex":"\\begin{bmatrix} 1\\cdot5 + 2\\cdot(-1) & 1\\cdot0 + 2\\cdot2 \\\\ 3\\cdot5 + 4\\cdot(-1) & 3\\cdot0 + 4\\cdot2 \\end{bmatrix}","explanation":"Row times column."},{"latex":"\\begin{bmatrix} 3 & 4 \\\\ 11 & 8 \\end{bmatrix}","explanation":""}],"check":"In the other order: $\\begin{bmatrix} 5 & 0 \\\\ -1 & 2 \\end{bmatrix}\\begin{bmatrix} 1 & 2 \\\\ 3 & 4 \\end{bmatrix} = \\begin{bmatrix} 5 & 10 \\\\ 5 & 6 \\end{bmatrix}$: a different result."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ce43f7b5fdc79', 'les_2fd8e2f269004d', 'learn', 4, 'callout', '{"tone":"warning","title":"Not commutative","body":"$AB$ and $BA$ are usually different, and one may be defined while the other isn''t."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_60f4a7ceab73e4', 'les_2fd8e2f269004d', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Graphics engines rotate and scale images with matrix multiplication, spreadsheets of prices times quantities are matrix products, and neural networks are built from matrix multiplications."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_45d949de1422d5', 'les_2fd8e2f269004d', 1, 'practice', 'multiple_choice', 1, 'A matrix has 3 rows and 4 columns. Its dimensions are…', '{"choices":["4 × 3","3 × 4","7","12 × 1"],"answer":1}', '[]', 'Rows × columns: 3 × 4.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5a8e7f92614575', 'les_2fd8e2f269004d', 2, 'practice', 'numeric', 2, '$A$ is 2 × 3 and $B$ is 3 × 5. How many entries does $AB$ have?', '{"answer":10}', '[]', '$AB$ is 2 × 5: 10 entries.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_868d52e2a5a3d7', 'les_2fd8e2f269004d', 3, 'practice', 'multiple_choice', 2, '$A$ is 2 × 3 and $B$ is 2 × 3. Which is defined?', '{"choices":["AB","A + B","BA","All of these"],"answer":1}', '[]', 'Same dimensions allow addition; neither product is defined.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1ce43f7b5fdc79', 'les_2fd8e2f269004d', 4, 'review', 'numeric', 3, 'Find the entry in row 2, column 1 of $\begin{bmatrix} 2 & -1 \\ 0 & 3 \end{bmatrix}\begin{bmatrix} 4 & 1 \\ 5 & -2 \end{bmatrix}$.', '{"answer":15}', '["Row 2 of the first times column 1 of the second."]', '$0 \cdot 4 + 3 \cdot 5 = 15$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_cebd95d917358f', 'subj_math', 'matrices', 'Matrices', 'Rectangular arrays of numbers with their own arithmetic.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2fd8e2f269004d', (SELECT id FROM concepts WHERE slug = 'matrices'));

-- Lesson: matrix-systems
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_265c126cdb0e7c', 'matrix-systems', 'Solving systems with matrices', 'Write a linear system as AX = B, solve it with an inverse matrix, and solve larger systems by row reduction of an augmented matrix.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_10e49e434dfd7a', 'les_265c126cdb0e7c', 1, 'Write a system as a matrix equation AX = B.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dd5223e55bf463', 'les_265c126cdb0e7c', 2, 'Solve 2 × 2 systems with X = A⁻¹B.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_286381296abfa0', 'les_265c126cdb0e7c', 3, 'Use row operations on an augmented matrix to solve systems of three equations.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10e49e434dfd7a', 'les_265c126cdb0e7c', 'learn', 1, 'text', '{"body":"The system $2x + 3y = 8$, $x - y = -1$ is the single matrix equation $\\begin{bmatrix} 2 & 3 \\\\ 1 & -1 \\end{bmatrix}\\begin{bmatrix} x \\\\ y \\end{bmatrix} = \\begin{bmatrix} 8 \\\\ -1 \\end{bmatrix}$, or $AX = B$. If $A$ has an inverse, $X = A^{-1}B$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dd5223e55bf463', 'les_265c126cdb0e7c', 'learn', 2, 'worked_example', '{"title":"Solve $2x + 3y = 8$, $x - y = -1$","steps":[{"latex":"\\det A = -2 - 3 = -5","explanation":""},{"latex":"A^{-1} = -\\tfrac{1}{5}\\begin{bmatrix} -1 & -3 \\\\ -1 & 2 \\end{bmatrix}","explanation":""},{"latex":"X = -\\tfrac{1}{5}\\begin{bmatrix} -8 + 3 \\\\ -8 - 2 \\end{bmatrix} = \\begin{bmatrix} 1 \\\\ 2 \\end{bmatrix}","explanation":"x = 1, y = 2."}],"check":"Check: $2 + 6 = 8$ ✓, $1 - 2 = -1$ ✓."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_286381296abfa0', 'les_265c126cdb0e7c', 'learn', 3, 'definition', '{"term":"Row reduction","body":"Write the augmented matrix $[A \\mid B]$. Use row operations (swap rows, multiply a row by a nonzero number, add a multiple of one row to another) to reach a form where each variable can be read off. These operations don''t change the solutions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_57539e225f8fd0', 'les_265c126cdb0e7c', 'learn', 4, 'worked_example', '{"title":"Solve $x + y + z = 6$, $2y + 5z = -4$, $2x + 5y - z = 27$","steps":[{"latex":"\\left[\\begin{array}{ccc|c} 1 & 1 & 1 & 6 \\\\ 0 & 2 & 5 & -4 \\\\ 2 & 5 & -1 & 27 \\end{array}\\right]","explanation":""},{"latex":"R_3 - 2R_1: \\ [0 \\ 3 \\ {-3} \\mid 15] \\Rightarrow y - z = 5","explanation":""},{"latex":"2y + 5z = -4,\\ y = z + 5 \\Rightarrow 7z = -14,\\ z = -2","explanation":""},{"latex":"y = 3,\\ x = 5","explanation":"Check the third equation: $10 + 15 + 2 = 27$. ✓"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ee574f31d6d998', 'les_265c126cdb0e7c', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers solve systems with thousands of unknowns (circuit analysis, structural loads) by row reduction on computers; GPS receivers solve small systems many times per second."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10e49e434dfd7a', 'les_265c126cdb0e7c', 1, 'practice', 'multiple_choice', 1, 'Which matrix equation represents $3x - y = 4$, $x + 2y = 5$?', '{"choices":["$\\begin{bmatrix} 3 & -1 \\\\ 1 & 2 \\end{bmatrix}\\begin{bmatrix} x \\\\ y \\end{bmatrix} = \\begin{bmatrix} 4 \\\\ 5 \\end{bmatrix}$","$\\begin{bmatrix} 3 & 1 \\\\ -1 & 2 \\end{bmatrix}\\begin{bmatrix} x \\\\ y \\end{bmatrix} = \\begin{bmatrix} 4 \\\\ 5 \\end{bmatrix}$","$\\begin{bmatrix} 4 \\\\ 5 \\end{bmatrix}\\begin{bmatrix} x & y \\end{bmatrix}$","$\\begin{bmatrix} 3 & -1 & 4 \\end{bmatrix}$"],"answer":0}', '[]', 'Coefficients by row.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dd5223e55bf463', 'les_265c126cdb0e7c', 2, 'practice', 'short_text', 2, 'Solve $3x - y = 4$, $x + 2y = 5$. Enter as (x,y).', '{"accept":["(13/7,11/7)"]}', '["$\\det = 7$."]', '$x = \frac{4 \cdot 2 + 5}{7} = \frac{13}{7}$, $y = \frac{15 - 4}{7} = \frac{11}{7}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_286381296abfa0', 'les_265c126cdb0e7c', 3, 'practice', 'multiple_choice', 2, 'If $\det A = 0$ for the system $AX = B$, then…', '{"choices":["There is exactly one solution","There is no unique solution","x = 0","B = 0"],"answer":1}', '[]', 'A isn''t invertible: no solution or infinitely many.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_57539e225f8fd0', 'les_265c126cdb0e7c', 4, 'review', 'short_text', 3, 'Solve $x + y = 3$, $y + z = 5$, $x + z = 4$. Enter as (x,y,z).', '{"accept":["(1,2,3)"]}', '["Add all three: 2(x + y + z) = 12."]', '$x + y + z = 6$, so $z = 3$, $x = 1$, $y = 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_cebd95d917358f', 'subj_math', 'matrices', 'Matrices', 'Rectangular arrays of numbers with their own arithmetic.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_265c126cdb0e7c', (SELECT id FROM concepts WHERE slug = 'matrices'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_265c126cdb0e7c', (SELECT id FROM concepts WHERE slug = 'systems-of-equations'));

-- Lesson: modeling-quadratics
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ee25adc21c38c4', 'modeling-quadratics', 'Modeling with quadratic functions', 'Build quadratic models for projectiles, areas and revenue, fit a quadratic through three points, and interpret the vertex and zeros in context.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0e5f20477e90cc', 'les_ee25adc21c38c4', 1, 'Model projectile height with h(t) = −16t² + v₀t + h₀ (feet) or −4.9t² + v₀t + h₀ (meters).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6201717bb59c29', 'les_ee25adc21c38c4', 2, 'Maximize area and revenue with the vertex.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6295620a3cc857', 'les_ee25adc21c38c4', 3, 'Find a quadratic through three points with a system of equations, and judge reasonable domains.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0e5f20477e90cc', 'les_ee25adc21c38c4', 'learn', 1, 'text', '{"body":"Quadratics model situations where something changes at a steadily changing rate: falling objects (gravity), areas (length × width), and revenue (price × quantity when quantity drops as price rises)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6201717bb59c29', 'les_ee25adc21c38c4', 'learn', 2, 'worked_example', '{"title":"A ball is thrown up from 6 ft at 48 ft/s: $h = -16t^2 + 48t + 6$. When does it land?","steps":[{"latex":"t = \\frac{-48 - \\sqrt{48^2 + 4(16)(6)}}{-32} = \\frac{-48 - \\sqrt{2688}}{-32}","explanation":"Quadratic formula with a = −16; take the positive root."},{"latex":"t \\approx \\frac{-48 - 51.85}{-32} \\approx 3.12 \\text{ s}","explanation":""}],"check":"The other root is negative and has no meaning here."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6295620a3cc857', 'les_ee25adc21c38c4', 'learn', 3, 'worked_example', '{"title":"A theater sells 300 tickets at 20 dollars; each 1-dollar increase loses 10 sales. What price maximizes revenue?","steps":[{"latex":"R(x) = (20 + x)(300 - 10x)","explanation":"x = number of 1-dollar increases."},{"latex":"\\text{zeros at } x = -20,\\ x = 30 \\Rightarrow \\text{vertex at } x = 5","explanation":"Halfway between the zeros."},{"latex":"\\text{price } 25,\\ R = 25 \\cdot 250 = 6250","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2be8a44465d016', 'les_ee25adc21c38c4', 'learn', 4, 'worked_example', '{"title":"Find the quadratic through $(0, 3)$, $(1, 2)$, $(2, 5)$","steps":[{"latex":"c = 3","explanation":"From (0, 3)."},{"latex":"a + b = -1,\\ 4a + 2b = 2","explanation":"From the other points."},{"latex":"a = 2,\\ b = -3 \\Rightarrow y = 2x^2 - 3x + 3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_42a6267f1f48f3', 'les_ee25adc21c38c4', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Sports analytics, bridge cables (approximately parabolic), pricing strategy and the design of satellite dishes all use quadratic models."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0e5f20477e90cc', 'les_ee25adc21c38c4', 1, 'practice', 'numeric', 2, 'A stone is dropped from 64 ft: $h = -16t^2 + 64$. When does it hit the ground, in seconds?', '{"answer":2,"unit":"s"}', '[]', '$16t^2 = 64$, $t = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6201717bb59c29', 'les_ee25adc21c38c4', 2, 'practice', 'numeric', 2, 'For $h = -16t^2 + 32t + 5$, what is the maximum height in feet?', '{"answer":21,"unit":"ft"}', '["$t = 1$."]', '$h(1) = -16 + 32 + 5 = 21$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6295620a3cc857', 'les_ee25adc21c38c4', 3, 'practice', 'numeric', 2, 'A rectangle has perimeter 40 m. What is its maximum possible area in m²?', '{"answer":100,"unit":"m²"}', '["$A = x(20 - x)$."]', 'Vertex at $x = 10$: a 10 by 10 square, area 100.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2be8a44465d016', 'les_ee25adc21c38c4', 4, 'review', 'numeric', 3, 'A quadratic passes through $(0, 1)$, $(1, 4)$ and $(2, 11)$. Find its leading coefficient $a$.', '{"answer":2}', '["$a + b = 3$, $4a + 2b = 10$."]', '$2a = 4$, $a = 2$ (and $b = 1$).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ee25adc21c38c4', (SELECT id FROM concepts WHERE slug = 'quadratic-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ee25adc21c38c4', (SELECT id FROM formulas WHERE slug = 'quadratic-formula'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ee25adc21c38c4', (SELECT id FROM formulas WHERE slug = 'vertex-form'), 2);

-- Lesson: number-e-continuous-growth
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f3a9dd6bdf3397', 'number-e-continuous-growth', 'The number e and continuous growth', 'See e emerge from compounding more and more often, use A = Pe^{rt} for continuous growth and decay, and compare compounding frequencies.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9ae003612419f1', 'les_f3a9dd6bdf3397', 1, 'Explain e as the limit of (1 + 1/n)^n as n grows.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_08ab69409a350a', 'les_f3a9dd6bdf3397', 2, 'Use A = P(1 + r/n)^{nt} and A = Pe^{rt}.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_98445c0a65f59a', 'les_f3a9dd6bdf3397', 3, 'Model continuous growth and decay and compare with discrete compounding.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9ae003612419f1', 'les_f3a9dd6bdf3397', 'learn', 1, 'text', '{"body":"Put 1 dollar in an account paying 100% a year. Compounded once: 2 dollars. Twice (50% each half-year): $1.5^2 = 2.25$. Monthly: $(1 + \\frac{1}{12})^{12} \\approx 2.613$. Daily: $\\approx 2.7146$. Compounding ever more often, the amount approaches a limit, $e \\approx 2.71828$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_08ab69409a350a', 'les_f3a9dd6bdf3397', 'learn', 2, 'definition', '{"term":"The number e","body":"$e = \\lim_{n \\to \\infty} \\left(1 + \\frac{1}{n}\\right)^n \\approx 2.71828$. It''s irrational, like $\\pi$. Continuous compounding at rate $r$ for $t$ years multiplies the principal by $e^{rt}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_98445c0a65f59a', 'les_f3a9dd6bdf3397', 'learn', 3, 'worked_example', '{"title":"5,000 dollars at 4% for 10 years: compare monthly and continuous compounding","steps":[{"latex":"5000\\left(1 + \\tfrac{0.04}{12}\\right)^{120} \\approx 7454.16","explanation":"Monthly."},{"latex":"5000e^{0.4} \\approx 7459.12","explanation":"Continuous: only about 5 dollars more."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_285ec502a89e16', 'les_f3a9dd6bdf3397', 'learn', 4, 'worked_example', '{"title":"A drug decays continuously at 12% per hour. Of 200 mg, how much remains after 5 hours?","steps":[{"latex":"A = 200e^{-0.12 \\cdot 5} = 200e^{-0.6}","explanation":""},{"latex":"\\approx 200(0.5488) \\approx 109.8 \\text{ mg}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_14c3476427edb8', 'les_f3a9dd6bdf3397', 'experiment', 5, 'activity', '{"activity":"exp-log","title":"The base e","params":{"b":2.7}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_84d959b01d66eb', 'les_f3a9dd6bdf3397', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"With base about 2.7, the exponential curve''s slope at $x = 0$ is about 1, which is the property that makes $e$ special in calculus. Its inverse is the natural logarithm, $\\ln x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9a8f26f538caaa', 'les_f3a9dd6bdf3397', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Continuous models describe population growth, radioactive decay, cooling, and interest in finance. $e$ shows up throughout calculus, probability and physics."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9ae003612419f1', 'les_f3a9dd6bdf3397', 1, 'practice', 'numeric', 1, 'Evaluate $e^2$ to two decimals.', '{"answer":7.39,"tolerance":0.006}', '[]', '$e^2 \approx 7.39$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_08ab69409a350a', 'les_f3a9dd6bdf3397', 2, 'practice', 'numeric', 2, '1,000 dollars grows continuously at 5% for 8 years. Find the balance to the nearest cent.', '{"answer":1491.82,"tolerance":0.01,"unit":"dollars"}', '["$1000e^{0.4}$."]', '$1000(1.491825) \approx 1491.82$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_98445c0a65f59a', 'les_f3a9dd6bdf3397', 3, 'practice', 'numeric', 2, '2,000 dollars at 6% compounded quarterly for 5 years. Find the balance to the nearest cent.', '{"answer":2693.71,"tolerance":0.01,"unit":"dollars"}', '["$2000(1.015)^{20}$."]', '$2000(1.346855) \approx 2693.71$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_285ec502a89e16', 'les_f3a9dd6bdf3397', 4, 'review', 'numeric', 3, 'A population of 800 grows continuously at 3% per year. What is it after 20 years, to the nearest whole number?', '{"answer":1458,"tolerance":0.5}', '["$800e^{0.6}$."]', '$800(1.822119) \approx 1458$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f3a9dd6bdf3397', (SELECT id FROM concepts WHERE slug = 'exponential-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f3a9dd6bdf3397', (SELECT id FROM formulas WHERE slug = 'continuous-growth'), 1);

-- Lesson: operations-on-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a4ba25724762b9', 'operations-on-functions', 'Operations on functions', 'Add, subtract, multiply and divide functions, evaluate the results, and find the domain of each combination.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d53341d8a4049c', 'les_a4ba25724762b9', 1, 'Form (f + g)(x), (f − g)(x), (fg)(x) and (f/g)(x).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dc82be97b30e56', 'les_a4ba25724762b9', 2, 'Evaluate combined functions at a value.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_609f4d739c56b7', 'les_a4ba25724762b9', 3, 'Find the domain of a combination, excluding zeros of the divisor.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d53341d8a4049c', 'les_a4ba25724762b9', 'learn', 1, 'definition', '{"term":"Function arithmetic","body":"$(f + g)(x) = f(x) + g(x)$, $(f - g)(x) = f(x) - g(x)$, $(fg)(x) = f(x)\\,g(x)$, and $\\left(\\frac{f}{g}\\right)(x) = \\frac{f(x)}{g(x)}$ where $g(x) \\ne 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc82be97b30e56', 'les_a4ba25724762b9', 'learn', 2, 'text', '{"body":"The domain of a sum, difference or product is the set of inputs in both domains. For a quotient, also remove every $x$ where the denominator function equals zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_609f4d739c56b7', 'les_a4ba25724762b9', 'learn', 3, 'worked_example', '{"title":"Let $f(x) = x^2 - 4$ and $g(x) = x + 2$. Find $f - g$, $fg$ and $\\frac{f}{g}$.","steps":[{"latex":"(f - g)(x) = x^2 - 4 - x - 2 = x^2 - x - 6","explanation":"Subtract the whole of g."},{"latex":"(fg)(x) = (x^2 - 4)(x + 2) = x^3 + 2x^2 - 4x - 8","explanation":""},{"latex":"\\left(\\tfrac{f}{g}\\right)(x) = \\tfrac{(x - 2)(x + 2)}{x + 2} = x - 2,\\ x \\ne -2","explanation":"The simplified form keeps the restriction from the original."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ca1ef9294c34c9', 'les_a4ba25724762b9', 'learn', 4, 'worked_example', '{"title":"With $f(x) = \\sqrt{x}$ and $g(x) = x - 3$, find the domain of $\\frac{f}{g}$.","steps":[{"latex":"x \\ge 0","explanation":"Domain of f."},{"latex":"x \\ne 3","explanation":"g(3) = 0."},{"latex":"[0, 3) \\cup (3, \\infty)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aaa830c59853f2', 'les_a4ba25724762b9', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Profit is revenue minus cost, $P(x) = R(x) - C(x)$; average cost is total cost divided by units, $\\frac{C(x)}{x}$. Business models are built by combining functions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d53341d8a4049c', 'les_a4ba25724762b9', 1, 'practice', 'short_text', 1, '$f(x) = 3x + 1$, $g(x) = x^2$. Find $(f + g)(x)$ in standard form.', '{"accept":["x^2+3x+1"]}', '[]', '$x^2 + 3x + 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dc82be97b30e56', 'les_a4ba25724762b9', 2, 'practice', 'numeric', 2, 'With the same functions, find $(fg)(2)$.', '{"answer":28}', '["$f(2) = 7$, $g(2) = 4$."]', '$7 \cdot 4 = 28$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_609f4d739c56b7', 'les_a4ba25724762b9', 3, 'practice', 'numeric', 2, 'With the same functions, find $(f - g)(-1)$.', '{"answer":-3}', '["$f(-1) = -2$, $g(-1) = 1$."]', '$-2 - 1 = -3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ca1ef9294c34c9', 'les_a4ba25724762b9', 4, 'practice', 'short_text', 2, '$f(x) = x + 5$ and $g(x) = x - 1$. Which x-value is excluded from the domain of $\frac{f}{g}$? Enter the number.', '{"accept":["1"]}', '[]', '$g(1) = 0$, so $x \ne 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aaa830c59853f2', 'les_a4ba25724762b9', 5, 'review', 'numeric', 3, 'Revenue is $R(x) = 25x$ and cost is $C(x) = 10x + 600$. Find the profit at $x = 100$.', '{"answer":900,"unit":"dollars"}', '["$P(x) = 15x - 600$."]', '$P(100) = 1500 - 600 = 900$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7925a166f49db8', 'subj_math', 'function-operations', 'Function operations', 'Combining functions by adding, subtracting, multiplying, dividing or composing.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a4ba25724762b9', (SELECT id FROM concepts WHERE slug = 'function-operations'));

-- Lesson: parent-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a77f628f760c22', 'parent-functions', 'Parent functions and their graphs', 'Recognize the graphs, domains, ranges and key features of the main parent functions, and identify the family a function belongs to.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d4e4d1be00be3a', 'les_a77f628f760c22', 1, 'Sketch the linear, quadratic, cubic, absolute value, square root, cube root, reciprocal and exponential parent functions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a27576dea3fc0a', 'les_a77f628f760c22', 2, 'State the domain, range, intercepts and end behavior of each.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_62f5697d95d53a', 'les_a77f628f760c22', 3, 'Identify the parent function of a transformed equation or graph.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d4e4d1be00be3a', 'les_a77f628f760c22', 'learn', 1, 'text', '{"body":"A function family is all the transformations of one simple parent function. Know the parent graphs well and every transformed function becomes a shift, stretch or reflection of a shape you already know."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a27576dea3fc0a', 'les_a77f628f760c22', 'learn', 2, 'definition', '{"term":"The main parents","body":"Linear $y = x$; quadratic $y = x^2$ (parabola, range $y \\ge 0$); cubic $y = x^3$ (S-shape, all reals); absolute value $y = |x|$ (V, range $y \\ge 0$); square root $y = \\sqrt{x}$ (domain and range $\\ge 0$); cube root $y = \\sqrt[3]{x}$ (all reals); reciprocal $y = \\frac{1}{x}$ (asymptotes $x = 0$ and $y = 0$); exponential $y = 2^x$ (range $y > 0$, asymptote $y = 0$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62f5697d95d53a', 'les_a77f628f760c22', 'learn', 3, 'worked_example', '{"title":"Identify the parent and describe $g(x) = -\\sqrt{x + 3}$","steps":[{"latex":"\\text{parent } y = \\sqrt{x}","explanation":""},{"latex":"\\text{left 3, reflected over the } x\\text{-axis}","explanation":"Domain x ≥ −3, range y ≤ 0."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a459356de6ce1e', 'les_a77f628f760c22', 'experiment', 4, 'activity', '{"activity":"polynomial-zeros","title":"Cubic and quadratic shapes","params":{"a":0.2,"r1":0,"m1":3,"r2":0,"m2":0,"r3":0,"m3":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a1af9707df2ce8', 'les_a77f628f760c22', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"This shows $y = 0.2x^3$, a scaled cubic parent. Change the multiplicity to 2 for a parabola shape. Which parents are symmetric about the y-axis (even) and which about the origin (odd)?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_34bb9256335070', 'les_a77f628f760c22', 'learn', 6, 'definition', '{"term":"Even and odd functions","body":"A function is even if $f(-x) = f(x)$ (symmetric about the y-axis), like $x^2$ and $|x|$. It is odd if $f(-x) = -f(x)$ (symmetric about the origin), like $x^3$, $\\frac{1}{x}$ and $\\sqrt[3]{x}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_945f122b19ffe9', 'les_a77f628f760c22', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Recognizing a family from data guides modeling: a falling object follows a quadratic, inverse-square laws follow a reciprocal-type curve, and populations follow exponentials."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d4e4d1be00be3a', 'les_a77f628f760c22', 1, 'practice', 'multiple_choice', 1, 'Which parent function has range $y \ge 0$ and a V shape?', '{"choices":["$y = x^2$","$y = |x|$","$y = \\sqrt{x}$","$y = x^3$"],"answer":1}', '[]', 'The absolute value function.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a27576dea3fc0a', 'les_a77f628f760c22', 2, 'practice', 'multiple_choice', 2, 'Which parent function has domain $x \ge 0$?', '{"choices":["$y = \\sqrt[3]{x}$","$y = \\sqrt{x}$","$y = \\frac{1}{x}$","$y = 2^x$"],"answer":1}', '[]', 'Square roots of negatives aren''t real.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_62f5697d95d53a', 'les_a77f628f760c22', 3, 'practice', 'multiple_choice', 2, 'What is the parent function of $f(x) = 3(x - 1)^3 + 2$?', '{"choices":["Quadratic","Cubic","Absolute value","Exponential"],"answer":1}', '[]', 'The cubic $y = x^3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a459356de6ce1e', 'les_a77f628f760c22', 4, 'practice', 'multiple_choice', 2, 'Which function is odd?', '{"choices":["$y = x^2$","$y = |x|$","$y = x^3$","$y = \\sqrt{x}$"],"answer":2}', '["Check $f(-x) = -f(x)$."]', '$(-x)^3 = -x^3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a1af9707df2ce8', 'les_a77f628f760c22', 5, 'review', 'short_text', 3, 'State the domain of $g(x) = \sqrt{x - 4} + 1$ as an inequality, like x>=…', '{"accept":["x>=4","x≥4"]}', '[]', '$x \ge 4$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4f5a7267f788c0', 'subj_math', 'function-families', 'Function families', 'Groups of functions that share a parent function and its basic shape.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a77f628f760c22', (SELECT id FROM concepts WHERE slug = 'function-families'));

-- Lesson: polynomial-graphs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d67a1dcea879d0', 'polynomial-graphs', 'Graphs of polynomial functions', 'Sketch polynomials from factored form using zeros, multiplicity, the y-intercept and end behavior.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5ae78ef885a04f', 'les_d67a1dcea879d0', 1, 'Find the zeros and their multiplicities from factored form.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0aada0f4346214', 'les_d67a1dcea879d0', 2, 'Explain how multiplicity determines whether a graph crosses or touches the x-axis.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eab1a04da6a394', 'les_d67a1dcea879d0', 3, 'Sketch a polynomial from its factored form and write a polynomial from a graph.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ae78ef885a04f', 'les_d67a1dcea879d0', 'learn', 1, 'definition', '{"term":"Multiplicity","body":"If $(x - r)^m$ is a factor, $r$ is a zero of multiplicity $m$. Odd multiplicity: the graph crosses the x-axis at $r$ (flattening if $m \\ge 3$). Even multiplicity: it touches and turns around."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0aada0f4346214', 'les_d67a1dcea879d0', 'experiment', 2, 'activity', '{"activity":"polynomial-zeros","title":"Zeros and multiplicity","params":{"a":0.25,"r1":-3,"m1":1,"r2":1,"m2":2,"r3":4,"m3":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eab1a04da6a394', 'les_d67a1dcea879d0', 'experiment', 3, 'callout', '{"tone":"tip","title":"Try this","body":"The graph touches at $x = 1$ (multiplicity 2) and crosses at $-3$ and $4$. Change multiplicity 2 to 3: the graph now flattens and crosses. Make $a$ negative and watch both ends flip."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4143961c5121ab', 'les_d67a1dcea879d0', 'learn', 4, 'worked_example', '{"title":"Sketch $f(x) = -(x + 2)(x - 1)^2$","steps":[{"latex":"\\text{zeros: } -2 \\text{ (cross)},\\ 1 \\text{ (touch)}","explanation":""},{"latex":"\\text{degree } 3,\\ \\text{leading coefficient } -1","explanation":"Left end up, right end down."},{"latex":"f(0) = -(2)(1) = -2","explanation":"y-intercept."}],"check":"Start high on the left, cross at −2, dip to the y-intercept −2, rise to touch at 1, then fall."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f64480e056b2e', 'les_d67a1dcea879d0', 'learn', 5, 'worked_example', '{"title":"Write a polynomial with zeros $-1$ (multiplicity 2) and $3$ that passes through $(0, 6)$","steps":[{"latex":"f(x) = a(x + 1)^2(x - 3)","explanation":""},{"latex":"6 = a(1)(-3) \\Rightarrow a = -2","explanation":""},{"latex":"f(x) = -2(x + 1)^2(x - 3)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_603a4d6eb31b94', 'les_d67a1dcea879d0', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Polynomial models approximate roller-coaster tracks, the volume of a box made by folding up corners of a sheet, and smooth curves in computer graphics."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5ae78ef885a04f', 'les_d67a1dcea879d0', 1, 'practice', 'multiple_choice', 1, 'At a zero of multiplicity 2, the graph…', '{"choices":["crosses the x-axis","touches and turns around","has an asymptote","is undefined"],"answer":1}', '[]', 'Even multiplicity: touches and turns.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0aada0f4346214', 'les_d67a1dcea879d0', 2, 'practice', 'short_text', 2, 'List the zeros of $f(x) = x(x - 4)^3(x + 5)^2$, smallest first.', '{"accept":["-5,0,4"]}', '[]', '$-5, 0, 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eab1a04da6a394', 'les_d67a1dcea879d0', 3, 'practice', 'numeric', 2, 'What is the degree of $f(x) = x(x - 4)^3(x + 5)^2$?', '{"answer":6}', '["Add the multiplicities."]', '$1 + 3 + 2 = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4143961c5121ab', 'les_d67a1dcea879d0', 4, 'practice', 'numeric', 2, 'Find the y-intercept of $f(x) = 2(x - 1)(x + 3)(x - 2)$.', '{"answer":12}', '[]', '$2(-1)(3)(-2) = 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5f64480e056b2e', 'les_d67a1dcea879d0', 5, 'review', 'numeric', 3, 'A polynomial has zeros 2 (multiplicity 1) and −1 (multiplicity 2), and $f(0) = -4$. Find the leading coefficient $a$ in $a(x - 2)(x + 1)^2$.', '{"answer":2}', '[]', '$-4 = a(-2)(1)$, so $a = 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_388c63c9c58169', 'subj_math', 'polynomial-functions', 'Polynomial functions', 'Functions built from sums of powers of x with whole-number exponents.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d67a1dcea879d0', (SELECT id FROM concepts WHERE slug = 'polynomial-functions'));

-- Lesson: properties-of-logarithms
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9c5c492f5e2dcb', 'properties-of-logarithms', 'Properties of logarithms', 'Derive and use the product, quotient and power rules and the change-of-base formula to expand, condense and evaluate logarithms.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a81f68ad5cf7fa', 'les_9c5c492f5e2dcb', 1, 'Explain the log rules from the exponent rules.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a73f7586be8779', 'les_9c5c492f5e2dcb', 2, 'Expand and condense logarithmic expressions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_21ba5f4085e4f7', 'les_9c5c492f5e2dcb', 3, 'Use the change-of-base formula to evaluate any logarithm.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a81f68ad5cf7fa', 'les_9c5c492f5e2dcb', 'learn', 1, 'definition', '{"term":"Rules","body":"For $M, N > 0$: $\\log_b(MN) = \\log_b M + \\log_b N$; $\\log_b \\frac{M}{N} = \\log_b M - \\log_b N$; $\\log_b M^p = p\\log_b M$; and change of base: $\\log_b M = \\frac{\\log M}{\\log b} = \\frac{\\ln M}{\\ln b}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a73f7586be8779', 'les_9c5c492f5e2dcb', 'learn', 2, 'text', '{"body":"Each rule is an exponent rule in disguise. If $M = b^m$ and $N = b^n$, then $MN = b^{m + n}$, so $\\log_b(MN) = m + n = \\log_b M + \\log_b N$. Logs turn multiplication into addition, which is why slide rules and log tables made calculation faster for centuries."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_21ba5f4085e4f7', 'les_9c5c492f5e2dcb', 'learn', 3, 'worked_example', '{"title":"Expand $\\log_3 \\dfrac{9x^2}{y}$","steps":[{"latex":"\\log_3 9 + \\log_3 x^2 - \\log_3 y","explanation":""},{"latex":"2 + 2\\log_3 x - \\log_3 y","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_abd091f548e82d', 'les_9c5c492f5e2dcb', 'learn', 4, 'worked_example', '{"title":"Condense $2\\ln x + \\ln 5 - \\tfrac{1}{2}\\ln y$","steps":[{"latex":"\\ln x^2 + \\ln 5 - \\ln \\sqrt{y}","explanation":"Power rule first."},{"latex":"\\ln \\frac{5x^2}{\\sqrt{y}}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_912bc15130dfc1', 'les_9c5c492f5e2dcb', 'learn', 5, 'worked_example', '{"title":"Evaluate $\\log_7 50$","steps":[{"latex":"\\frac{\\ln 50}{\\ln 7} \\approx \\frac{3.9120}{1.9459} \\approx 2.0104","explanation":"Change of base."}],"check":"Check: $7^2 = 49$, so a value just over 2 makes sense."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4ba32c031ab51b', 'les_9c5c492f5e2dcb', 'learn', 6, 'callout', '{"tone":"warning","title":"No rule for sums","body":"$\\log(M + N) \\ne \\log M + \\log N$, and $\\frac{\\log M}{\\log N} \\ne \\log \\frac{M}{N}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7a120c084487a6', 'les_9c5c492f5e2dcb', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"An earthquake one magnitude higher releases about 32 times as much energy, because magnitude is a logarithm; doubling a sound''s intensity adds about 3 decibels ($10\\log 2$)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a81f68ad5cf7fa', 'les_9c5c492f5e2dcb', 1, 'practice', 'short_text', 2, 'Expand $\log(100x^3)$. Use the format 2+3log(x).', '{"accept":["2+3log(x)","2+3logx"]}', '[]', '$\log 100 + 3\log x = 2 + 3\log x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a73f7586be8779', 'les_9c5c492f5e2dcb', 2, 'practice', 'short_text', 2, 'Condense $\log_2 x + \log_2 8$. Use the format log_2(8x).', '{"accept":["log_2(8x)","log2(8x)"]}', '[]', '$\log_2 8x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_21ba5f4085e4f7', 'les_9c5c492f5e2dcb', 3, 'practice', 'numeric', 2, 'Evaluate $\log_2 12 - \log_2 3$.', '{"answer":2}', '[]', '$\log_2 4 = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_abd091f548e82d', 'les_9c5c492f5e2dcb', 4, 'practice', 'numeric', 2, 'Evaluate $\log_5 30$ to three decimals.', '{"answer":2.113,"tolerance":0.0006}', '["$\\frac{\\ln 30}{\\ln 5}$."]', '$3.4012 / 1.6094 \approx 2.113$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_912bc15130dfc1', 'les_9c5c492f5e2dcb', 5, 'review', 'multiple_choice', 3, 'If $\log_b 2 \approx 0.3$ and $\log_b 3 \approx 0.5$, what is $\log_b 18$?', '{"choices":["0.8","1.1","1.3","0.15"],"answer":2}', '["$18 = 2 \\cdot 3^2$."]', '$0.3 + 2(0.5) = 1.3$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_98ef8be0f3a311', 'subj_math', 'logarithms', 'Logarithms', 'Exponents: log_b x is the power of b that gives x.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9c5c492f5e2dcb', (SELECT id FROM concepts WHERE slug = 'logarithms'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9c5c492f5e2dcb', (SELECT id FROM formulas WHERE slug = 'log-properties'), 1);

-- Lesson: pythagorean-identity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5cbc7fb7e3ffab', 'pythagorean-identity', 'The Pythagorean identity', 'Prove sin²θ + cos²θ = 1 from the unit circle and use it to find one trig value from another, given the quadrant.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1185004bfca833', 'les_5cbc7fb7e3ffab', 1, 'Prove the Pythagorean identity using the unit circle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eeee5709cafdea', 'les_5cbc7fb7e3ffab', 2, 'Find sin θ, cos θ or tan θ from one known value and the quadrant.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dec4d37d0941d6', 'les_5cbc7fb7e3ffab', 3, 'Derive the related identities 1 + tan²θ = sec²θ and 1 + cot²θ = csc²θ.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1185004bfca833', 'les_5cbc7fb7e3ffab', 'learn', 1, 'text', '{"body":"The point at angle $\\theta$ on the unit circle is $(\\cos\\theta, \\sin\\theta)$, and it lies on $x^2 + y^2 = 1$. Substituting gives the identity for every angle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eeee5709cafdea', 'les_5cbc7fb7e3ffab', 'learn', 2, 'definition', '{"term":"Pythagorean identity","body":"$\\sin^2\\theta + \\cos^2\\theta = 1$. Dividing by $\\cos^2\\theta$ gives $\\tan^2\\theta + 1 = \\sec^2\\theta$; dividing by $\\sin^2\\theta$ gives $1 + \\cot^2\\theta = \\csc^2\\theta$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dec4d37d0941d6', 'les_5cbc7fb7e3ffab', 'experiment', 3, 'activity', '{"activity":"unit-circle","title":"The point stays on x² + y² = 1"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8fdfed4ae9f6d8', 'les_5cbc7fb7e3ffab', 'learn', 4, 'worked_example', '{"title":"$\\sin\\theta = \\tfrac{3}{5}$ with $\\theta$ in Quadrant II. Find $\\cos\\theta$ and $\\tan\\theta$.","steps":[{"latex":"\\cos^2\\theta = 1 - \\tfrac{9}{25} = \\tfrac{16}{25}","explanation":""},{"latex":"\\cos\\theta = -\\tfrac{4}{5}","explanation":"Cosine is negative in Quadrant II."},{"latex":"\\tan\\theta = \\tfrac{3/5}{-4/5} = -\\tfrac{3}{4}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9af733992e9f90', 'les_5cbc7fb7e3ffab', 'learn', 5, 'callout', '{"tone":"warning","title":"Choose the sign by quadrant","body":"Taking a square root gives ±. Sine is positive in Quadrants I and II, cosine in I and IV, tangent in I and III."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b57b1acd8320d1', 'les_5cbc7fb7e3ffab', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Physics resolves forces into components whose squares add to the whole; signal processing, navigation and computer graphics use this identity to keep rotations accurate."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1185004bfca833', 'les_5cbc7fb7e3ffab', 1, 'practice', 'numeric', 1, 'If $\cos\theta = 0.6$, what is $\sin^2\theta$?', '{"answer":0.64}', '[]', '$1 - 0.36 = 0.64$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eeee5709cafdea', 'les_5cbc7fb7e3ffab', 2, 'practice', 'short_text', 2, '$\cos\theta = -\frac{5}{13}$ in Quadrant III. Find $\sin\theta$.', '{"accept":["-12/13"]}', '[]', '$\sin^2\theta = \frac{144}{169}$, negative in QIII: $-\frac{12}{13}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dec4d37d0941d6', 'les_5cbc7fb7e3ffab', 3, 'practice', 'short_text', 2, 'With the same angle, find $\tan\theta$.', '{"accept":["12/5"]}', '[]', '$\frac{-12/13}{-5/13} = \frac{12}{5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8fdfed4ae9f6d8', 'les_5cbc7fb7e3ffab', 4, 'review', 'multiple_choice', 3, 'Simplify $\frac{1 - \cos^2\theta}{\sin\theta}$ (sin θ ≠ 0).', '{"choices":["$\\cos\\theta$","$\\sin\\theta$","$1$","$\\tan\\theta$"],"answer":1}', '[]', '$\frac{\sin^2\theta}{\sin\theta} = \sin\theta$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d36dc660725d5f', 'subj_math', 'trig-identities', 'Trigonometric identities', 'Equations involving trig functions that are true for every allowed angle.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5cbc7fb7e3ffab', (SELECT id FROM concepts WHERE slug = 'trig-identities'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5cbc7fb7e3ffab', (SELECT id FROM formulas WHERE slug = 'pythagorean-identity'), 1);

-- Lesson: quadratic-forms
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_87ff4bd0954169', 'quadratic-forms', 'Vertex, standard and factored forms', 'Move between the three forms of a quadratic and choose the form that reveals the feature you need: vertex, y-intercept or zeros.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_19ae66f7032c03', 'les_87ff4bd0954169', 1, 'Read the vertex from vertex form, the y-intercept from standard form and the zeros from factored form.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_acf7a43cfe7f55', 'les_87ff4bd0954169', 2, 'Convert between forms by expanding, factoring and completing the square.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_11b4315081b8e7', 'les_87ff4bd0954169', 3, 'Write a quadratic from its zeros and one other point.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_19ae66f7032c03', 'les_87ff4bd0954169', 'learn', 1, 'definition', '{"term":"Three forms","body":"Standard: $y = ax^2 + bx + c$ (y-intercept $c$). Vertex: $y = a(x - h)^2 + k$ (vertex $(h, k)$). Factored: $y = a(x - p)(x - q)$ (zeros $p$ and $q$; axis of symmetry halfway between, $x = \\frac{p + q}{2}$). All three have the same $a$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_acf7a43cfe7f55', 'les_87ff4bd0954169', 'learn', 2, 'worked_example', '{"title":"Write $y = 2x^2 - 4x - 6$ in factored and vertex forms","steps":[{"latex":"y = 2(x^2 - 2x - 3) = 2(x - 3)(x + 1)","explanation":"Factor: zeros 3 and −1."},{"latex":"h = \\tfrac{3 + (-1)}{2} = 1,\\ k = 2(1)^2 - 4 - 6 = -8","explanation":"Vertex halfway between the zeros."},{"latex":"y = 2(x - 1)^2 - 8","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_11b4315081b8e7', 'les_87ff4bd0954169', 'learn', 3, 'worked_example', '{"title":"Write the quadratic with zeros $-2$ and 5 that passes through $(3, -20)$","steps":[{"latex":"y = a(x + 2)(x - 5)","explanation":""},{"latex":"-20 = a(5)(-2) \\Rightarrow a = 2","explanation":""},{"latex":"y = 2(x + 2)(x - 5) = 2x^2 - 6x - 20","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2a8cb6761759f9', 'les_87ff4bd0954169', 'experiment', 4, 'activity', '{"activity":"vertex-explorer","title":"Vertex form and expanded form together","params":{"a":2,"h":1,"k":-4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f1679d96dae1fb', 'les_87ff4bd0954169', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"The readouts show the zeros and the expanded (standard) form for the vertex form you set. Move the vertex so the zeros are integers, then write the factored form yourself."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b54b9bad58d33a', 'les_87ff4bd0954169', 'learn', 6, 'callout', '{"tone":"warning","title":"Not every quadratic factors over the reals","body":"If the parabola doesn''t cross the x-axis (for example $y = x^2 + 4$), it has no real zeros and no real factored form. Its zeros are complex, as the next lessons show."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f168e823490f69', 'les_87ff4bd0954169', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"An engineer uses vertex form for the maximum height of an arch, factored form for where it meets the ground, and standard form for its height at the center line (x = 0)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_19ae66f7032c03', 'les_87ff4bd0954169', 1, 'practice', 'short_text', 1, 'What is the vertex of $y = -3(x + 4)^2 + 7$? Enter as (h,k).', '{"accept":["(-4,7)"]}', '[]', '$(-4, 7)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_acf7a43cfe7f55', 'les_87ff4bd0954169', 2, 'practice', 'short_text', 2, 'What are the zeros of $y = 5(x - 2)(x + 6)$? Enter both, smaller first.', '{"accept":["-6,2"]}', '[]', '$-6$ and $2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_11b4315081b8e7', 'les_87ff4bd0954169', 3, 'practice', 'short_text', 2, 'Write $y = (x - 3)^2 - 4$ in standard form.', '{"accept":["x^2-6x+5"]}', '[]', '$x^2 - 6x + 9 - 4 = x^2 - 6x + 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2a8cb6761759f9', 'les_87ff4bd0954169', 4, 'practice', 'short_text', 2, 'Write $y = x^2 + 2x - 15$ in factored form.', '{"accept":["(x+5)(x-3)","(x-3)(x+5)"]}', '[]', '$(x + 5)(x - 3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f1679d96dae1fb', 'les_87ff4bd0954169', 5, 'review', 'multiple_choice', 3, 'A parabola has zeros 1 and 7 and vertex $(4, -18)$. What is $a$?', '{"choices":["1","2","−2","−18"],"answer":1}', '["$y = a(x - 1)(x - 7)$ at $x = 4$."]', '$-18 = a(3)(-3)$, so $a = 2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_87ff4bd0954169', (SELECT id FROM concepts WHERE slug = 'quadratic-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_87ff4bd0954169', (SELECT id FROM formulas WHERE slug = 'vertex-form'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_87ff4bd0954169', (SELECT id FROM formulas WHERE slug = 'quadratic-formula'), 2);

-- Lesson: quadratics-complex-solutions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_985d4fa194964d', 'quadratics-complex-solutions', 'Solving quadratics with complex solutions', 'Solve quadratics whose discriminant is negative, write complex solutions in a + bi form, and connect them to parabolas that miss the x-axis.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e201054042c87f', 'les_985d4fa194964d', 1, 'Use the discriminant to predict real or complex solutions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c677d433022d5d', 'les_985d4fa194964d', 2, 'Solve quadratics with complex solutions by square roots, completing the square or the quadratic formula.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2c4bb182fbe2ee', 'les_985d4fa194964d', 3, 'Explain why complex solutions of real quadratics come in conjugate pairs.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e201054042c87f', 'les_985d4fa194964d', 'learn', 1, 'text', '{"body":"When $b^2 - 4ac < 0$, the quadratic formula asks for the square root of a negative number. With $i$, that''s no longer a dead end: the equation has two complex solutions, and the parabola $y = ax^2 + bx + c$ simply doesn''t cross the x-axis."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c677d433022d5d', 'les_985d4fa194964d', 'learn', 2, 'worked_example', '{"title":"Solve $x^2 + 2x + 5 = 0$","steps":[{"latex":"x = \\frac{-2 \\pm \\sqrt{4 - 20}}{2} = \\frac{-2 \\pm \\sqrt{-16}}{2}","explanation":""},{"latex":"= \\frac{-2 \\pm 4i}{2} = -1 \\pm 2i","explanation":""}],"check":"Check $-1 + 2i$: $(-1 + 2i)^2 = 1 - 4i - 4 = -3 - 4i$; then $-3 - 4i + 2(-1 + 2i) + 5 = 0$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2c4bb182fbe2ee', 'les_985d4fa194964d', 'learn', 3, 'worked_example', '{"title":"Solve $3(x - 4)^2 + 27 = 0$","steps":[{"latex":"(x - 4)^2 = -9","explanation":""},{"latex":"x - 4 = \\pm 3i \\Rightarrow x = 4 \\pm 3i","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c7402386fd12a', 'les_985d4fa194964d', 'experiment', 4, 'activity', '{"activity":"vertex-explorer","title":"No x-intercepts means complex zeros","params":{"a":1,"h":-1,"k":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4bc957eb5f3efc', 'les_985d4fa194964d', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"This parabola, $y = (x + 1)^2 + 4 = x^2 + 2x + 5$, has no real zeros. Its vertex is $(-1, 4)$ and its complex zeros are $-1 \\pm 2i$: the real part matches the axis of symmetry."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_500d19b0c10a4c', 'les_985d4fa194964d', 'learn', 6, 'callout', '{"tone":"note","title":"Conjugate pairs","body":"If a quadratic has real coefficients, its complex solutions are conjugates $a \\pm bi$, because the $\\pm$ in the formula produces both."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c17576b808c24', 'les_985d4fa194964d', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"In physics, complex solutions of a quadratic describe oscillation: a damped spring with a negative discriminant bounces back and forth instead of settling smoothly."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e201054042c87f', 'les_985d4fa194964d', 1, 'practice', 'multiple_choice', 1, 'What does a negative discriminant tell you?', '{"choices":["Two real solutions","One real solution","Two complex (non-real) solutions","No solutions at all"],"answer":2}', '[]', 'Two complex conjugate solutions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c677d433022d5d', 'les_985d4fa194964d', 2, 'practice', 'short_text', 2, 'Solve $x^2 + 25 = 0$. Enter like ±5i.', '{"accept":["±5i","+-5i","5i,-5i","-5i,5i"]}', '[]', '$x = \pm 5i$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2c4bb182fbe2ee', 'les_985d4fa194964d', 3, 'practice', 'short_text', 2, 'Solve $x^2 - 4x + 13 = 0$. Enter like 2±3i.', '{"accept":["2±3i","2+-3i"]}', '["$\\frac{4 \\pm \\sqrt{16 - 52}}{2}$."]', '$\frac{4 \pm 6i}{2} = 2 \pm 3i$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c7402386fd12a', 'les_985d4fa194964d', 4, 'review', 'short_text', 3, 'Solve $(x + 2)^2 = -12$. Enter like -2±2sqrt(3)i.', '{"accept":["-2±2sqrt(3)i","-2±2i√3","-2±2√3i","-2±2isqrt(3)"]}', '["$\\sqrt{-12} = 2i\\sqrt{3}$."]', '$x = -2 \pm 2i\sqrt{3}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d7a3ca35193c15', 'subj_math', 'complex-numbers', 'Complex numbers', 'Numbers a + bi with real a and b, where i² = −1.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_985d4fa194964d', (SELECT id FROM concepts WHERE slug = 'complex-numbers'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_985d4fa194964d', (SELECT id FROM concepts WHERE slug = 'discriminant'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_985d4fa194964d', (SELECT id FROM formulas WHERE slug = 'quadratic-formula'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_985d4fa194964d', (SELECT id FROM formulas WHERE slug = 'discriminant'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_985d4fa194964d', (SELECT id FROM formulas WHERE slug = 'complex-numbers'), 3);

-- Lesson: rational-expression-operations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e0fa321724ff51', 'rational-expression-operations', 'Adding, subtracting, multiplying and dividing rational expressions', 'Perform the four operations on rational expressions using the same rules as fractions, with factoring and least common denominators.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3562373782eccd', 'les_e0fa321724ff51', 1, 'Multiply and divide rational expressions and simplify.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b6be9169d23b94', 'les_e0fa321724ff51', 2, 'Find the least common denominator of rational expressions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_759ceb0c0d0d15', 'les_e0fa321724ff51', 3, 'Add and subtract rational expressions and simplify complex fractions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3562373782eccd', 'les_e0fa321724ff51', 'learn', 1, 'text', '{"body":"Rational expressions follow exactly the rules of numeric fractions. Multiply straight across, divide by multiplying by the reciprocal, and add or subtract only over a common denominator. Factor everything first; it makes canceling and finding the LCD easy."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b6be9169d23b94', 'les_e0fa321724ff51', 'learn', 2, 'worked_example', '{"title":"Multiply $\\dfrac{x^2 - 1}{x + 3} \\cdot \\dfrac{x + 3}{x^2 - x}$","steps":[{"latex":"\\frac{(x - 1)(x + 1)}{x + 3} \\cdot \\frac{x + 3}{x(x - 1)}","explanation":""},{"latex":"\\frac{x + 1}{x}","explanation":"Cancel x + 3 and x − 1."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_759ceb0c0d0d15', 'les_e0fa321724ff51', 'learn', 3, 'worked_example', '{"title":"Add $\\dfrac{3}{x - 2} + \\dfrac{5}{x + 1}$","steps":[{"latex":"\\text{LCD} = (x - 2)(x + 1)","explanation":""},{"latex":"\\frac{3(x + 1) + 5(x - 2)}{(x - 2)(x + 1)} = \\frac{8x - 7}{(x - 2)(x + 1)}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2fc3684d98ae9f', 'les_e0fa321724ff51', 'learn', 4, 'worked_example', '{"title":"Subtract $\\dfrac{x}{x^2 - 9} - \\dfrac{1}{x + 3}$","steps":[{"latex":"\\frac{x - (x - 3)}{(x - 3)(x + 3)}","explanation":"LCD (x − 3)(x + 3). Distribute the subtraction."},{"latex":"\\frac{3}{(x - 3)(x + 3)}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f1b1c166cddc7', 'les_e0fa321724ff51', 'learn', 5, 'callout', '{"tone":"warning","title":"Subtract the whole numerator","body":"When subtracting, put parentheses around the second numerator before distributing the minus sign."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d4806ad714d50', 'les_e0fa321724ff51', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Combined work rates ($\\frac{1}{a} + \\frac{1}{b}$), resistors in parallel and average speeds over round trips all add rational expressions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3562373782eccd', 'les_e0fa321724ff51', 1, 'practice', 'short_text', 2, 'Multiply $\dfrac{2x}{x + 5} \cdot \dfrac{x + 5}{6}$. Use the format x/3.', '{"accept":["x/3"]}', '[]', '$\frac{2x}{6} = \frac{x}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b6be9169d23b94', 'les_e0fa321724ff51', 2, 'practice', 'short_text', 2, 'Divide $\dfrac{x^2 - 4}{3x} \div \dfrac{x - 2}{6}$. Use the format 2(x+2)/x.', '{"accept":["2(x+2)/x","(2x+4)/x"]}', '[]', '$\frac{(x - 2)(x + 2)}{3x} \cdot \frac{6}{x - 2} = \frac{2(x + 2)}{x}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_759ceb0c0d0d15', 'les_e0fa321724ff51', 3, 'practice', 'short_text', 2, 'Add $\dfrac{2}{x} + \dfrac{3}{x + 1}$. Use the format (5x+2)/(x(x+1)).', '{"accept":["(5x+2)/(x(x+1))","(5x+2)/(x^2+x)"]}', '[]', '$\frac{2(x + 1) + 3x}{x(x + 1)} = \frac{5x + 2}{x(x + 1)}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2fc3684d98ae9f', 'les_e0fa321724ff51', 4, 'review', 'short_text', 3, 'Simplify $\dfrac{4}{x - 1} - \dfrac{4}{x + 1}$. Use the format 8/((x-1)(x+1)).', '{"accept":["8/((x-1)(x+1))","8/(x^2-1)"]}', '[]', '$\frac{4(x + 1) - 4(x - 1)}{(x - 1)(x + 1)} = \frac{8}{x^2 - 1}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7db461ca62c4d7', 'subj_math', 'rational-expressions', 'Rational expressions', 'Ratios of polynomials, defined where the denominator is not zero.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e0fa321724ff51', (SELECT id FROM concepts WHERE slug = 'rational-expressions'));

-- Lesson: rational-function-graphs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4098270f6a3765', 'rational-function-graphs', 'Graphs of rational functions and asymptotes', 'Find vertical and horizontal asymptotes, holes, intercepts and domain of rational functions, and sketch their graphs.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_54c89b48c2f186', 'les_4098270f6a3765', 1, 'Graph transformations of y = 1/x and identify their asymptotes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9228fb75800300', 'les_4098270f6a3765', 2, 'Find vertical asymptotes and holes from the factored denominator.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e36f29f8fe6ab6', 'les_4098270f6a3765', 3, 'Find horizontal asymptotes by comparing degrees.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_54c89b48c2f186', 'les_4098270f6a3765', 'experiment', 1, 'activity', '{"activity":"rational-graph","title":"Shift and stretch 1/x","params":{"a":2,"h":1,"k":-1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9228fb75800300', 'les_4098270f6a3765', 'experiment', 2, 'callout', '{"tone":"tip","title":"Try this","body":"The dashed lines are the asymptotes $x = h$ and $y = k$. Move $h$ and $k$: the asymptotes move with the graph. What happens to the curve when $a$ is negative?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e36f29f8fe6ab6', 'les_4098270f6a3765', 'learn', 3, 'definition', '{"term":"Vertical asymptotes and holes","body":"Factor and simplify $f(x) = \\frac{P(x)}{Q(x)}$. A factor that cancels gives a hole at that $x$. A zero of the denominator that remains after canceling gives a vertical asymptote."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb540007767a65', 'les_4098270f6a3765', 'learn', 4, 'definition', '{"term":"Horizontal asymptote","body":"Compare the degrees $n$ (numerator) and $d$ (denominator). If $n < d$: $y = 0$. If $n = d$: $y = \\frac{\\text{leading coefficient of } P}{\\text{leading coefficient of } Q}$. If $n > d$: no horizontal asymptote."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f68b66f7a8aa2c', 'les_4098270f6a3765', 'learn', 5, 'worked_example', '{"title":"Analyze $f(x) = \\dfrac{2x^2 - 2}{x^2 - 3x + 2}$","steps":[{"latex":"\\frac{2(x - 1)(x + 1)}{(x - 1)(x - 2)}","explanation":"Factor."},{"latex":"\\text{hole at } x = 1,\\ \\text{VA } x = 2","explanation":"x − 1 cancels; x − 2 remains."},{"latex":"\\text{HA } y = \\tfrac{2}{1} = 2","explanation":"Equal degrees."},{"latex":"x\\text{-intercept } -1,\\ y\\text{-intercept } f(0) = -1","explanation":""}],"check":"The hole is at $\\left(1, \\frac{2(2)}{-1}\\right) = (1, -4)$, from the simplified form $\\frac{2(x + 1)}{x - 2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bccb850b90b31f', 'les_4098270f6a3765', 'learn', 6, 'callout', '{"tone":"warning","title":"A graph can cross a horizontal asymptote","body":"Horizontal asymptotes describe end behavior only. The graph may cross one at a finite $x$; it can never cross a vertical asymptote."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d346218b2225e1', 'les_4098270f6a3765', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Average cost per item, $\\frac{C}{x}$, falls toward a horizontal asymptote as production grows; drug concentration and lens equations also have asymptotes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_54c89b48c2f186', 'les_4098270f6a3765', 1, 'practice', 'short_text', 1, 'Find the vertical asymptote of $f(x) = \dfrac{3}{x + 4}$. Enter like x=….', '{"accept":["x=-4"]}', '[]', '$x = -4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9228fb75800300', 'les_4098270f6a3765', 2, 'practice', 'short_text', 2, 'Find the horizontal asymptote of $f(x) = \dfrac{6x + 1}{2x - 5}$. Enter like y=….', '{"accept":["y=3"]}', '["Equal degrees."]', '$y = \frac{6}{2} = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e36f29f8fe6ab6', 'les_4098270f6a3765', 3, 'practice', 'short_text', 2, 'Find the horizontal asymptote of $f(x) = \dfrac{x + 2}{x^2 - 1}$.', '{"accept":["y=0"]}', '[]', 'Numerator degree is lower: $y = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cb540007767a65', 'les_4098270f6a3765', 4, 'practice', 'multiple_choice', 2, 'Where does $f(x) = \dfrac{x^2 - 9}{x - 3}$ have a hole?', '{"choices":["$x = 3$","$x = -3$","$x = 9$","No hole"],"answer":0}', '[]', '$x - 3$ cancels, leaving $x + 3$ with a hole at $x = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f68b66f7a8aa2c', 'les_4098270f6a3765', 5, 'review', 'short_text', 3, 'Find the vertical asymptote(s) of $f(x) = \dfrac{x - 1}{x^2 - x - 6}$, smaller first, like x=a,x=b.', '{"accept":["x=-2,x=3"]}', '["$(x - 3)(x + 2)$."]', '$x = -2$ and $x = 3$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0c2683c1416f53', 'subj_math', 'rational-functions', 'Rational functions', 'Functions that are ratios of polynomials, with asymptotes and holes.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4098270f6a3765', (SELECT id FROM concepts WHERE slug = 'rational-functions'));

-- Lesson: remainder-factor-theorems
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_07b471b48c918a', 'remainder-factor-theorems', 'The Remainder and Factor Theorems', 'Use the Remainder Theorem to evaluate polynomials quickly and the Factor Theorem to test factors and factor polynomials completely.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_868f757d73fbd4', 'les_07b471b48c918a', 1, 'State and use the Remainder Theorem: the remainder of P(x) ÷ (x − c) is P(c).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4c496f9b8b2fd3', 'les_07b471b48c918a', 2, 'State and use the Factor Theorem: x − c is a factor exactly when P(c) = 0.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_663fc6c386c75a', 'les_07b471b48c918a', 3, 'Factor a polynomial completely given one zero.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_868f757d73fbd4', 'les_07b471b48c918a', 'learn', 1, 'definition', '{"term":"Remainder Theorem","body":"When $P(x)$ is divided by $x - c$, the remainder is $P(c)$. Reason: $P(x) = (x - c)Q(x) + R$; substituting $x = c$ gives $P(c) = R$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c496f9b8b2fd3', 'les_07b471b48c918a', 'learn', 2, 'definition', '{"term":"Factor Theorem","body":"$x - c$ is a factor of $P(x)$ if and only if $P(c) = 0$, that is, $c$ is a zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_663fc6c386c75a', 'les_07b471b48c918a', 'learn', 3, 'worked_example', '{"title":"Is $x + 2$ a factor of $P(x) = x^3 + 4x^2 + x - 6$? Factor completely.","steps":[{"latex":"P(-2) = -8 + 16 - 2 - 6 = 0","explanation":"Yes, x + 2 is a factor."},{"latex":"P(x) = (x + 2)(x^2 + 2x - 3)","explanation":"Synthetic division by −2 gives 1, 2, −3, 0."},{"latex":"= (x + 2)(x + 3)(x - 1)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0338baf5ccea1d', 'les_07b471b48c918a', 'learn', 4, 'worked_example', '{"title":"Find $k$ so that $x - 1$ is a factor of $2x^3 + kx^2 - 5x + 1$","steps":[{"latex":"P(1) = 2 + k - 5 + 1 = 0","explanation":""},{"latex":"k = 2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ac7a2c31151e9', 'les_07b471b48c918a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Computer algebra systems test candidate factors with these theorems, and evaluating P(c) by synthetic division is how calculators compute polynomial values efficiently (Horner''s method)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_868f757d73fbd4', 'les_07b471b48c918a', 1, 'practice', 'numeric', 1, 'What is the remainder when $P(x) = x^3 - 4x + 1$ is divided by $x - 2$?', '{"answer":1}', '["$P(2)$."]', '$8 - 8 + 1 = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4c496f9b8b2fd3', 'les_07b471b48c918a', 2, 'practice', 'multiple_choice', 2, 'Which is a factor of $x^3 - 6x^2 + 11x - 6$?', '{"choices":["$x + 1$","$x - 1$","$x + 2$","$x - 4$"],"answer":1}', '["Test P(c) = 0."]', '$P(1) = 1 - 6 + 11 - 6 = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_663fc6c386c75a', 'les_07b471b48c918a', 3, 'practice', 'short_text', 2, 'Factor completely: $x^3 - 6x^2 + 11x - 6$.', '{"accept":["(x-1)(x-2)(x-3)"]}', '["Divide by x − 1."]', '$(x - 1)(x^2 - 5x + 6) = (x - 1)(x - 2)(x - 3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0338baf5ccea1d', 'les_07b471b48c918a', 4, 'review', 'numeric', 3, 'Find $k$ so that $x + 3$ is a factor of $x^3 + kx - 6$.', '{"answer":-11}', '["$P(-3) = 0$."]', '$-27 - 3k - 6 = 0$, $k = -11$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_bdebb0664fa40f', 'subj_math', 'polynomial-division', 'Polynomial division', 'Dividing polynomials by long or synthetic division to find a quotient and remainder.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_07b471b48c918a', (SELECT id FROM concepts WHERE slug = 'polynomial-division'));

-- Lesson: sampling-surveys
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_adf4d0c89d17c2', 'sampling-surveys', 'Sampling and surveys', 'Distinguish populations from samples, compare sampling methods, recognize bias, and tell surveys, observational studies and experiments apart.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c831734ea38114', 'les_adf4d0c89d17c2', 1, 'Distinguish a population, a sample, a parameter and a statistic.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3cba451ac0283a', 'les_adf4d0c89d17c2', 2, 'Describe random, stratified, cluster, systematic and convenience samples.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_63d58f523adc14', 'les_adf4d0c89d17c2', 3, 'Identify sources of bias and distinguish surveys, observational studies and experiments.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c831734ea38114', 'les_adf4d0c89d17c2', 'learn', 1, 'definition', '{"term":"Population and sample","body":"The population is the entire group of interest; a sample is the part you actually measure. A number describing the population is a parameter; the same number computed from a sample is a statistic, which estimates it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3cba451ac0283a', 'les_adf4d0c89d17c2', 'learn', 2, 'definition', '{"term":"Sampling methods","body":"Simple random: every group of size n is equally likely. Stratified: split into groups (strata) and randomly sample each. Cluster: randomly choose whole groups. Systematic: every kth member. Convenience: whoever is easy to reach (usually biased)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_63d58f523adc14', 'les_adf4d0c89d17c2', 'learn', 3, 'text', '{"body":"Bias is a systematic error that pushes results in one direction. Common sources: undercoverage (some groups can''t be selected), nonresponse (selected people don''t answer), voluntary response (only people with strong opinions reply), and leading question wording."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ca8bd20cce4208', 'les_adf4d0c89d17c2', 'learn', 4, 'worked_example', '{"title":"A school wants students'' opinion on lunch. Evaluate: surveying the first 50 students in the lunch line.","steps":[{"latex":"\\text{convenience sample}","explanation":"Students who skip lunch or come late are left out: undercoverage."},{"latex":"\\text{better: stratified random by grade}","explanation":"Randomly select students from each grade''s roster."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_58763dfa15df72', 'les_adf4d0c89d17c2', 'learn', 5, 'definition', '{"term":"Study types","body":"A survey asks questions. An observational study measures without intervening. An experiment randomly assigns treatments, which is the only design that can show cause and effect."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6499f812f0fb5b', 'les_adf4d0c89d17c2', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Election polls, product reviews, medical trials and census planning all depend on good sampling. A large biased sample is worse than a small random one."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c831734ea38114', 'les_adf4d0c89d17c2', 1, 'practice', 'multiple_choice', 1, 'A poll of 1,000 voters finds 52% support. The 52% is a…', '{"choices":["parameter","statistic","population","census"],"answer":1}', '[]', 'It describes the sample.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3cba451ac0283a', 'les_adf4d0c89d17c2', 2, 'practice', 'multiple_choice', 2, 'A radio host asks listeners to call in their opinion. What''s the main problem?', '{"choices":["Too small","Voluntary response bias","Stratification","Nothing"],"answer":1}', '[]', 'Only people with strong opinions call.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_63d58f523adc14', 'les_adf4d0c89d17c2', 3, 'practice', 'multiple_choice', 2, 'Choosing 20 students at random from each grade is…', '{"choices":["Simple random","Stratified random","Cluster","Systematic"],"answer":1}', '[]', 'Random within each stratum (grade).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ca8bd20cce4208', 'les_adf4d0c89d17c2', 4, 'review', 'multiple_choice', 3, 'Which study can establish that a new fertilizer causes taller plants?', '{"choices":["Survey of farmers","Observational study of farms","Randomized experiment with control plots","Convenience sample of gardens"],"answer":2}', '[]', 'Random assignment controls for other variables.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_b8e00fdd472eae', 'subj_math', 'sampling', 'Sampling', 'Choosing part of a population to learn about the whole.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_adf4d0c89d17c2', (SELECT id FROM concepts WHERE slug = 'sampling'));

-- Lesson: sigma-notation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0d6defa4826fc6', 'sigma-notation', 'Sigma notation', 'Read and write sums with Σ notation, evaluate them, and use properties of sums and the series formulas.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_68bf01b0e7f535', 'les_0d6defa4826fc6', 1, 'Read the index, limits and expression in Σ notation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0aa4adc6a71707', 'les_0d6defa4826fc6', 2, 'Write a series in Σ notation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_22efeea0bd60fb', 'les_0d6defa4826fc6', 3, 'Evaluate sums by listing terms or using series formulas.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_68bf01b0e7f535', 'les_0d6defa4826fc6', 'learn', 1, 'definition', '{"term":"Sigma notation","body":"$\\displaystyle\\sum_{k=1}^{n} a_k = a_1 + a_2 + \\cdots + a_n$. The index $k$ starts at the lower limit and goes up by 1 to the upper limit."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0aa4adc6a71707', 'les_0d6defa4826fc6', 'learn', 2, 'worked_example', '{"title":"Evaluate $\\displaystyle\\sum_{k=1}^{5} (2k + 1)$","steps":[{"latex":"3 + 5 + 7 + 9 + 11","explanation":""},{"latex":"35","explanation":"Or: arithmetic with 5 terms, $\\frac{5(3 + 11)}{2} = 35$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22efeea0bd60fb', 'les_0d6defa4826fc6', 'learn', 3, 'worked_example', '{"title":"Write $4 + 8 + 16 + \\cdots + 1024$ in sigma notation","steps":[{"latex":"4 = 2^2,\\ 1024 = 2^{10}","explanation":""},{"latex":"\\sum_{k=2}^{10} 2^k","explanation":"Or equivalently $\\sum_{k=1}^{9} 4 \\cdot 2^{k-1}$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0709e1ace6b728', 'les_0d6defa4826fc6', 'learn', 4, 'definition', '{"term":"Properties","body":"$\\sum (a_k + b_k) = \\sum a_k + \\sum b_k$, $\\sum c\\,a_k = c\\sum a_k$, and $\\sum_{k=1}^{n} c = cn$. Also $\\sum_{k=1}^{n} k = \\frac{n(n + 1)}{2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_38afcc61244b0a', 'les_0d6defa4826fc6', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Statistics formulas (the mean is $\\frac{1}{n}\\sum x_i$), spreadsheet SUM functions, and the integrals of calculus all use sigma notation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_68bf01b0e7f535', 'les_0d6defa4826fc6', 1, 'practice', 'numeric', 1, 'Evaluate $\sum_{k=1}^{4} k^2$.', '{"answer":30}', '[]', '$1 + 4 + 9 + 16 = 30$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0aa4adc6a71707', 'les_0d6defa4826fc6', 2, 'practice', 'numeric', 2, 'Evaluate $\sum_{k=1}^{100} 3$.', '{"answer":300}', '[]', '300.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22efeea0bd60fb', 'les_0d6defa4826fc6', 3, 'practice', 'numeric', 2, 'Evaluate $\sum_{k=1}^{20} (4k - 1)$.', '{"answer":820}', '["$4 \\cdot 210 - 20$."]', '$840 - 20 = 820$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0709e1ace6b728', 'les_0d6defa4826fc6', 4, 'review', 'short_text', 3, 'Write $5 + 10 + 15 + \cdots + 100$ in sigma notation, using k from 1. Use the format sum_(k=1)^20 5k.', '{"accept":["sum_(k=1)^205k","sum_(k=1)^(20)5k"]}', '["How many terms?"]', '$\sum_{k=1}^{20} 5k$ (sum 1050).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8c45d090913a21', 'subj_math', 'series', 'Series', 'The sum of the terms of a sequence.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0d6defa4826fc6', (SELECT id FROM concepts WHERE slug = 'series'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0d6defa4826fc6', (SELECT id FROM formulas WHERE slug = 'series-sums'), 1);

-- Lesson: simplifying-rational-expressions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_97be1af90c0d1a', 'simplifying-rational-expressions', 'Simplifying rational expressions', 'Simplify rational expressions by factoring and canceling common factors, and state the values excluded from the domain.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c520240f53141e', 'les_97be1af90c0d1a', 1, 'Identify excluded values of a rational expression.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b677015978a178', 'les_97be1af90c0d1a', 2, 'Simplify by factoring numerator and denominator and canceling common factors.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a7544d23ce85b2', 'les_97be1af90c0d1a', 3, 'Recognize opposite factors such as (a − b) and (b − a).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c520240f53141e', 'les_97be1af90c0d1a', 'learn', 1, 'definition', '{"term":"Rational expression","body":"A ratio $\\frac{P(x)}{Q(x)}$ of polynomials. It is undefined where $Q(x) = 0$; those values are excluded from the domain."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b677015978a178', 'les_97be1af90c0d1a', 'learn', 2, 'worked_example', '{"title":"Simplify $\\dfrac{x^2 - 9}{x^2 + 5x + 6}$","steps":[{"latex":"\\frac{(x - 3)(x + 3)}{(x + 2)(x + 3)}","explanation":"Factor both."},{"latex":"\\frac{x - 3}{x + 2},\\quad x \\ne -2,\\ -3","explanation":"Cancel the common factor; keep both excluded values from the original."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a7544d23ce85b2', 'les_97be1af90c0d1a', 'learn', 3, 'worked_example', '{"title":"Simplify $\\dfrac{4 - x}{x^2 - 16}$","steps":[{"latex":"\\frac{-(x - 4)}{(x - 4)(x + 4)}","explanation":"$4 - x = -(x - 4)$."},{"latex":"-\\frac{1}{x + 4},\\quad x \\ne \\pm 4","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4e4e41c390fab2', 'les_97be1af90c0d1a', 'learn', 4, 'callout', '{"tone":"warning","title":"Cancel factors, never terms","body":"In $\\frac{x + 5}{x}$ nothing cancels: the $x$ in the numerator is a term, not a factor. Only factors of the entire numerator and denominator can be divided out."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44df0a685a3f32', 'les_97be1af90c0d1a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Average cost $\\frac{C(x)}{x}$, rates of work, and lens and circuit formulas are rational expressions; simplifying makes them easier to evaluate and analyze."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c520240f53141e', 'les_97be1af90c0d1a', 1, 'practice', 'short_text', 1, 'Simplify $\dfrac{6x^3}{9x}$ for $x \ne 0$. Use the format 2x^2/3.', '{"accept":["2x^2/3","(2/3)x^2"]}', '[]', '$\frac{2x^2}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b677015978a178', 'les_97be1af90c0d1a', 2, 'practice', 'short_text', 2, 'Simplify $\dfrac{x^2 - 4x}{x^2 - 16}$. Use the format x/(x+4).', '{"accept":["x/(x+4)"]}', '[]', '$\frac{x(x - 4)}{(x - 4)(x + 4)} = \frac{x}{x + 4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a7544d23ce85b2', 'les_97be1af90c0d1a', 3, 'practice', 'short_text', 2, 'Simplify $\dfrac{x^2 + x - 12}{x^2 - 9}$.', '{"accept":["(x+4)/(x+3)"]}', '[]', '$\frac{(x + 4)(x - 3)}{(x - 3)(x + 3)} = \frac{x + 4}{x + 3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4e4e41c390fab2', 'les_97be1af90c0d1a', 4, 'practice', 'multiple_choice', 2, 'Which values are excluded from $\dfrac{x + 1}{x^2 - 5x + 6}$?', '{"choices":["−1","2 and 3","−2 and −3","none"],"answer":1}', '[]', '$(x - 2)(x - 3) = 0$ at 2 and 3.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_44df0a685a3f32', 'les_97be1af90c0d1a', 5, 'review', 'short_text', 3, 'Simplify $\dfrac{5 - x}{x^2 - 25}$. Use the format -1/(x+5).', '{"accept":["-1/(x+5)"]}', '[]', '$\frac{-(x - 5)}{(x - 5)(x + 5)} = -\frac{1}{x + 5}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7db461ca62c4d7', 'subj_math', 'rational-expressions', 'Rational expressions', 'Ratios of polynomials, defined where the denominator is not zero.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_97be1af90c0d1a', (SELECT id FROM concepts WHERE slug = 'rational-expressions'));

-- Lesson: sine-cosine-graphs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b45eaaff92f393', 'sine-cosine-graphs', 'Graphs of sine and cosine', 'Build the sine and cosine graphs from the unit circle and identify their period, amplitude, midline, zeros, maximums and minimums.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_87e3a1e4d0cc68', 'les_b45eaaff92f393', 1, 'Generate the graphs of y = sin x and y = cos x from the unit circle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3db8cf8ed7944b', 'les_b45eaaff92f393', 2, 'Identify period, amplitude, midline, zeros and extrema of the parent graphs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f7d8785dc6585a', 'les_b45eaaff92f393', 3, 'Relate sine and cosine as horizontal shifts of each other.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87e3a1e4d0cc68', 'les_b45eaaff92f393', 'learn', 1, 'text', '{"body":"As an angle $x$ (in radians) turns around the unit circle, $\\sin x$ is the height of the point and $\\cos x$ is its horizontal position. Plot those values against $x$ and you get waves that repeat every $2\\pi$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3db8cf8ed7944b', 'les_b45eaaff92f393', 'experiment', 2, 'activity', '{"activity":"unit-circle","title":"Trace sine and cosine on the unit circle"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f7d8785dc6585a', 'les_b45eaaff92f393', 'learn', 3, 'definition', '{"term":"Key features","body":"Both have period $2\\pi$, amplitude 1, midline $y = 0$ and range $[-1, 1]$. $\\sin x$: zeros at $0, \\pi, 2\\pi$; max at $\\frac{\\pi}{2}$; min at $\\frac{3\\pi}{2}$. $\\cos x$: max at $0$; zeros at $\\frac{\\pi}{2}, \\frac{3\\pi}{2}$; min at $\\pi$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_60638da1194f7b', 'les_b45eaaff92f393', 'learn', 4, 'text', '{"body":"The cosine graph is the sine graph shifted left by $\\frac{\\pi}{2}$: $\\cos x = \\sin\\left(x + \\frac{\\pi}{2}\\right)$. Sine is odd (symmetric about the origin) and cosine is even (symmetric about the y-axis)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4efbed0d2d191f', 'les_b45eaaff92f393', 'experiment', 5, 'activity', '{"activity":"sinusoid","title":"Switch between sin and cos","params":{"A":1,"B":1,"C":0,"D":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0b5510475f4004', 'les_b45eaaff92f393', 'learn', 6, 'worked_example', '{"title":"Where on $[0, 2\\pi]$ is $\\sin x = -1$, and what is $\\cos\\pi$?","steps":[{"latex":"x = \\tfrac{3\\pi}{2}","explanation":"The bottom of the unit circle."},{"latex":"\\cos\\pi = -1","explanation":"The leftmost point."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d7dde7fc7531fd', 'les_b45eaaff92f393', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Sound waves, alternating current, tides, daylight hours over a year and circular motion are all modeled by sine and cosine."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87e3a1e4d0cc68', 'les_b45eaaff92f393', 1, 'practice', 'numeric', 1, 'What is the period of $y = \sin x$, as a multiple of π? Enter the coefficient (for 2π, enter 2).', '{"answer":2}', '[]', '$2\pi$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3db8cf8ed7944b', 'les_b45eaaff92f393', 2, 'practice', 'multiple_choice', 2, 'Where on $[0, 2\pi)$ does $\cos x = 0$?', '{"choices":["$0, \\pi$","$\\frac{\\pi}{2}, \\frac{3\\pi}{2}$","$\\frac{\\pi}{4}, \\frac{5\\pi}{4}$","$\\pi$ only"],"answer":1}', '[]', 'At the top and bottom of the unit circle.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f7d8785dc6585a', 'les_b45eaaff92f393', 3, 'practice', 'multiple_choice', 2, 'Which is true?', '{"choices":["$\\sin x = \\cos\\left(x - \\frac{\\pi}{2}\\right)$","$\\sin x = \\cos x$ for all x","$\\cos x = -\\sin x$","$\\sin(-x) = \\sin x$"],"answer":0}', '[]', 'Cosine shifted right by $\frac{\pi}{2}$ is sine.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_60638da1194f7b', 'les_b45eaaff92f393', 4, 'review', 'numeric', 3, 'What is the maximum value of $y = \cos x$ on $[0, 2\pi]$, and at how many points does it occur? Enter the number of points.', '{"answer":2}', '["Max 1 at x = 0 and x = 2π."]', 'Two points: $0$ and $2\pi$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_fcedb559562f5a', 'subj_math', 'trig-functions', 'Trigonometric functions', 'Sine, cosine and related functions of an angle, defined on the unit circle.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b45eaaff92f393', (SELECT id FROM concepts WHERE slug = 'trig-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b45eaaff92f393', (SELECT id FROM formulas WHERE slug = 'sinusoid'), 1);

-- Lesson: slant-asymptotes-holes
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b80d1d591790f0', 'slant-asymptotes-holes', 'Slant asymptotes and holes', 'Find slant (oblique) asymptotes by polynomial division when the numerator''s degree is one more than the denominator''s, and locate holes precisely.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1aa28acf56d6ea', 'les_b80d1d591790f0', 1, 'Identify when a rational function has a slant asymptote.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0e2d6fad4a0f69', 'les_b80d1d591790f0', 2, 'Find the slant asymptote by division.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_02353a34486ff2', 'les_b80d1d591790f0', 3, 'Find the coordinates of holes and sketch the complete graph.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1aa28acf56d6ea', 'les_b80d1d591790f0', 'learn', 1, 'definition', '{"term":"Slant asymptote","body":"If the numerator''s degree is exactly one more than the denominator''s, divide: $f(x) = mx + b + \\frac{R(x)}{Q(x)}$. As $|x| \\to \\infty$ the remainder fraction goes to 0, so the graph approaches the line $y = mx + b$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0e2d6fad4a0f69', 'les_b80d1d591790f0', 'learn', 2, 'worked_example', '{"title":"Find the asymptotes of $f(x) = \\dfrac{x^2 + x - 1}{x - 1}$","steps":[{"latex":"\\frac{x^2 + x - 1}{x - 1} = x + 2 + \\frac{1}{x - 1}","explanation":"Divide (synthetic with c = 1: 1, 2, 1)."},{"latex":"\\text{slant: } y = x + 2;\\ \\text{vertical: } x = 1","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_02353a34486ff2', 'les_b80d1d591790f0', 'learn', 3, 'worked_example', '{"title":"Find the hole of $g(x) = \\dfrac{x^2 - x - 6}{x^2 - 9}$","steps":[{"latex":"\\frac{(x - 3)(x + 2)}{(x - 3)(x + 3)} = \\frac{x + 2}{x + 3},\\ x \\ne 3","explanation":""},{"latex":"\\text{hole at } \\left(3, \\tfrac{5}{6}\\right)","explanation":"Evaluate the simplified form at x = 3."},{"latex":"\\text{VA } x = -3,\\ \\text{HA } y = 1","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dfacafe5813856', 'les_b80d1d591790f0', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Average-cost and efficiency curves often have slant asymptotes, describing how a quantity behaves almost linearly at large scale."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1aa28acf56d6ea', 'les_b80d1d591790f0', 1, 'practice', 'short_text', 2, 'Find the slant asymptote of $f(x) = \dfrac{x^2 + 3x + 5}{x + 1}$. Use the format y=x+2.', '{"accept":["y=x+2"]}', '["Divide: 1, 2, remainder 3."]', '$x + 2 + \frac{3}{x + 1}$, so $y = x + 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0e2d6fad4a0f69', 'les_b80d1d591790f0', 2, 'practice', 'short_text', 2, 'Find the slant asymptote of $f(x) = \dfrac{2x^2 - 1}{x}$.', '{"accept":["y=2x"]}', '[]', '$2x - \frac{1}{x}$: $y = 2x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_02353a34486ff2', 'les_b80d1d591790f0', 3, 'practice', 'multiple_choice', 2, 'Which function has a slant asymptote?', '{"choices":["$\\frac{x^2}{x^2 + 1}$","$\\frac{x^3}{x^2 + 1}$","$\\frac{x}{x^2 + 1}$","$\\frac{x^4}{x + 1}$"],"answer":1}', '["Numerator degree exactly one more."]', 'Degrees 3 and 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dfacafe5813856', 'les_b80d1d591790f0', 4, 'review', 'short_text', 3, 'Find the hole of $f(x) = \dfrac{x^2 - 1}{x - 1}$. Enter as (x,y).', '{"accept":["(1,2)"]}', '[]', '$f = x + 1$ for $x \ne 1$; hole at $(1, 2)$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0c2683c1416f53', 'subj_math', 'rational-functions', 'Rational functions', 'Functions that are ratios of polynomials, with asymptotes and holes.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b80d1d591790f0', (SELECT id FROM concepts WHERE slug = 'rational-functions'));

-- Lesson: solving-radical-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f4d6457ebe1f85', 'solving-radical-equations', 'Solving radical equations', 'Solve equations with square roots, cube roots and rational exponents by isolating the radical and raising both sides to a power, checking for extraneous solutions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a84d032ae905f4', 'les_f4d6457ebe1f85', 1, 'Isolate a radical and raise both sides to the matching power.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0857381d048d24', 'les_f4d6457ebe1f85', 2, 'Solve equations with two radicals and with rational exponents.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f7718b5297862c', 'les_f4d6457ebe1f85', 3, 'Identify extraneous solutions introduced by squaring.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a84d032ae905f4', 'les_f4d6457ebe1f85', 'learn', 1, 'text', '{"body":"To undo a square root, square both sides; to undo a cube root, cube them. Squaring is not reversible ($3^2 = (-3)^2$), so it can create extraneous solutions. Cubing can''t, but checking is always wise."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0857381d048d24', 'les_f4d6457ebe1f85', 'learn', 2, 'worked_example', '{"title":"Solve $\\sqrt{x + 7} - x = 1$","steps":[{"latex":"\\sqrt{x + 7} = x + 1","explanation":"Isolate the radical."},{"latex":"x + 7 = x^2 + 2x + 1 \\Rightarrow x^2 + x - 6 = 0","explanation":"Square both sides."},{"latex":"x = 2 \\text{ or } x = -3","explanation":""},{"latex":"x = 2: 3 - 2 = 1 ✓;\\quad x = -3: 2 + 3 = 5 ✗","explanation":"Only x = 2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f7718b5297862c', 'les_f4d6457ebe1f85', 'learn', 3, 'worked_example', '{"title":"Solve $(x - 2)^{3/2} = 8$","steps":[{"latex":"x - 2 = 8^{2/3} = 4","explanation":"Raise both sides to the 2/3 power."},{"latex":"x = 6","explanation":"Check: $4^{3/2} = 8$. ✓"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d4bd96f65869d7', 'les_f4d6457ebe1f85', 'learn', 4, 'worked_example', '{"title":"Solve $\\sqrt{x + 5} = \\sqrt{x} + 1$","steps":[{"latex":"x + 5 = x + 2\\sqrt{x} + 1","explanation":"Square; the right side is a binomial."},{"latex":"4 = 2\\sqrt{x} \\Rightarrow x = 4","explanation":"Check: $3 = 2 + 1$. ✓"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_36648a553378bb', 'les_f4d6457ebe1f85', 'learn', 5, 'callout', '{"tone":"warning","title":"Square the whole side","body":"$(\\sqrt{x} + 1)^2 = x + 2\\sqrt{x} + 1$, not $x + 1$. Forgetting the middle term is the most common error."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d1742ecca2d103', 'les_f4d6457ebe1f85', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pendulum periods ($T = 2\\pi\\sqrt{L/g}$), stopping distance from speed, and the time for an object to fall all lead to radical equations when you solve for the length or distance."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a84d032ae905f4', 'les_f4d6457ebe1f85', 1, 'practice', 'numeric', 1, 'Solve $\sqrt{2x - 1} = 5$.', '{"answer":13}', '[]', '$2x - 1 = 25$, $x = 13$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0857381d048d24', 'les_f4d6457ebe1f85', 2, 'practice', 'numeric', 2, 'Solve $\sqrt[3]{x + 4} = -2$.', '{"answer":-12}', '[]', '$x + 4 = -8$, $x = -12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f7718b5297862c', 'les_f4d6457ebe1f85', 3, 'practice', 'numeric', 2, 'Solve $\sqrt{3x + 1} = x - 3$ (enter the valid solution).', '{"answer":8}', '["$3x + 1 = x^2 - 6x + 9$."]', '$x^2 - 9x + 8 = 0$, $x = 1$ or $8$. $x = 1$ gives $2 = -2$ ✗, so $x = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d4bd96f65869d7', 'les_f4d6457ebe1f85', 4, 'practice', 'numeric', 2, 'Solve $x^{2/3} = 9$ for the positive solution.', '{"answer":27}', '["Raise to the 3/2 power."]', '$x = \pm 27$; the positive one is 27.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_36648a553378bb', 'les_f4d6457ebe1f85', 5, 'review', 'short_text', 3, 'Solve $\sqrt{x} + 6 = 2$. Enter the solution or "none".', '{"accept":["none","nosolution"]}', '["$\\sqrt{x} = -4$."]', 'A principal square root can''t be negative, so there''s no solution (squaring would give the extraneous 16).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f4d6457ebe1f85', (SELECT id FROM concepts WHERE slug = 'radical-functions'));

-- Lesson: solving-rational-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_71e90b1e230b3b', 'solving-rational-equations', 'Solving rational equations', 'Solve rational equations by multiplying by the LCD, check for extraneous solutions, and solve work and rate problems.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f1740481c224a5', 'les_71e90b1e230b3b', 1, 'Clear denominators by multiplying both sides by the LCD.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3c0fc4dea76eda', 'les_71e90b1e230b3b', 2, 'Identify extraneous solutions that make a denominator zero.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_73937581cdb3d9', 'les_71e90b1e230b3b', 3, 'Solve work, rate and mixture problems modeled by rational equations.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f1740481c224a5', 'les_71e90b1e230b3b', 'learn', 1, 'text', '{"body":"Multiplying every term by the least common denominator turns a rational equation into a polynomial equation. But that step can introduce solutions that make an original denominator zero. Those are extraneous and must be rejected."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c0fc4dea76eda', 'les_71e90b1e230b3b', 'learn', 2, 'worked_example', '{"title":"Solve $\\dfrac{x}{x - 3} = \\dfrac{3}{x - 3} + 2$","steps":[{"latex":"x = 3 + 2(x - 3)","explanation":"Multiply by x − 3."},{"latex":"x = 2x - 3 \\Rightarrow x = 3","explanation":""},{"latex":"x = 3 \\text{ makes a denominator } 0","explanation":"Extraneous: no solution."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_73937581cdb3d9', 'les_71e90b1e230b3b', 'learn', 3, 'worked_example', '{"title":"Solve $\\dfrac{2}{x} + \\dfrac{1}{x + 2} = 1$","steps":[{"latex":"2(x + 2) + x = x(x + 2)","explanation":"LCD x(x + 2)."},{"latex":"3x + 4 = x^2 + 2x \\Rightarrow x^2 - x - 4 = 0","explanation":""},{"latex":"x = \\frac{1 \\pm \\sqrt{17}}{2} \\approx 2.56,\\ -1.56","explanation":"Neither is 0 or −2, so both are valid."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c509ae44004f53', 'les_71e90b1e230b3b', 'learn', 4, 'worked_example', '{"title":"One pump fills a tank in 6 hours and another in 3 hours. How long together?","steps":[{"latex":"\\tfrac{t}{6} + \\tfrac{t}{3} = 1","explanation":"Fraction of the job each does in t hours."},{"latex":"t + 2t = 6 \\Rightarrow t = 2 \\text{ h}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_13a2dd339404dd', 'les_71e90b1e230b3b', 'learn', 5, 'callout', '{"tone":"warning","title":"Always check","body":"List the excluded values before solving, and compare your answers against them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0bfdc1e979893d', 'les_71e90b1e230b3b', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Work rates, average speeds, lens equations ($\\frac{1}{f} = \\frac{1}{d_o} + \\frac{1}{d_i}$) and parallel resistors all lead to rational equations."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f1740481c224a5', 'les_71e90b1e230b3b', 1, 'practice', 'numeric', 1, 'Solve $\dfrac{12}{x} = 4$.', '{"answer":3}', '[]', '$x = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3c0fc4dea76eda', 'les_71e90b1e230b3b', 2, 'practice', 'numeric', 2, 'Solve $\dfrac{x + 1}{x - 2} = 4$.', '{"answer":3}', '["$x + 1 = 4x - 8$."]', '$3x = 9$, $x = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_73937581cdb3d9', 'les_71e90b1e230b3b', 3, 'practice', 'short_text', 2, 'Solve $\dfrac{x^2}{x - 1} = \dfrac{1}{x - 1}$. Enter the solution, or "none".', '{"accept":["-1","x=-1"]}', '["$x^2 = 1$, but $x = 1$ is excluded."]', '$x = \pm 1$; $x = 1$ is extraneous, so $x = -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c509ae44004f53', 'les_71e90b1e230b3b', 4, 'practice', 'numeric', 2, 'Ana paints a room in 4 hours; Ben in 12 hours. How many hours together?', '{"answer":3,"unit":"h"}', '["$\\frac{t}{4} + \\frac{t}{12} = 1$."]', '$3t + t = 12$, $t = 3$ hours.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_13a2dd339404dd', 'les_71e90b1e230b3b', 5, 'review', 'numeric', 3, 'A boat goes 24 km downstream and 24 km back in 5 hours total. The current is 2 km/h. What is the boat''s speed in still water?', '{"answer":10,"unit":"km/h"}', '["$\\frac{24}{b + 2} + \\frac{24}{b - 2} = 5$."]', '$48b = 5(b^2 - 4)$, so $5b^2 - 48b - 20 = 0$ and $b = 10$ (the other root is negative).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7db461ca62c4d7', 'subj_math', 'rational-expressions', 'Rational expressions', 'Ratios of polynomials, defined where the denominator is not zero.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_71e90b1e230b3b', (SELECT id FROM concepts WHERE slug = 'rational-expressions'));

-- Lesson: tangent-reciprocal-graphs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9277e9be997c2a', 'tangent-reciprocal-graphs', 'Graphs of tangent and reciprocal functions', 'Graph tangent, cotangent, secant and cosecant, and identify their periods, asymptotes, domains and ranges.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0fa6e4eb683533', 'les_9277e9be997c2a', 1, 'Graph y = tan x and find its period and vertical asymptotes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_491cc755bcf149', 'les_9277e9be997c2a', 2, 'Graph secant, cosecant and cotangent from their reciprocal functions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0ca46141b86284', 'les_9277e9be997c2a', 3, 'State the domain, range and period of each and transform tangent graphs.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0fa6e4eb683533', 'les_9277e9be997c2a', 'learn', 1, 'definition', '{"term":"Tangent","body":"$\\tan x = \\frac{\\sin x}{\\cos x}$. It''s undefined where $\\cos x = 0$, so it has vertical asymptotes at $x = \\frac{\\pi}{2} + k\\pi$. Its period is $\\pi$, its range is all reals, and it passes through $(0, 0)$ increasing."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_491cc755bcf149', 'les_9277e9be997c2a', 'learn', 2, 'definition', '{"term":"Reciprocal functions","body":"$\\csc x = \\frac{1}{\\sin x}$, $\\sec x = \\frac{1}{\\cos x}$, $\\cot x = \\frac{1}{\\tan x}$. Each has asymptotes where its reciprocal is 0. Secant and cosecant have period $2\\pi$ and range $(-\\infty, -1] \\cup [1, \\infty)$; cotangent has period $\\pi$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0ca46141b86284', 'les_9277e9be997c2a', 'learn', 3, 'text', '{"body":"To sketch $\\sec x$, sketch $\\cos x$ lightly first. Wherever cosine is 1 or −1, secant equals it; as cosine shrinks toward 0, secant grows without bound, producing U-shaped branches between asymptotes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bba5f8ef1dcb71', 'les_9277e9be997c2a', 'learn', 4, 'worked_example', '{"title":"Find the period and asymptotes of $y = \\tan(2x)$","steps":[{"latex":"\\text{period} = \\tfrac{\\pi}{2}","explanation":"Tangent''s period π divided by B = 2."},{"latex":"2x = \\tfrac{\\pi}{2} + k\\pi \\Rightarrow x = \\tfrac{\\pi}{4} + \\tfrac{k\\pi}{2}","explanation":"Asymptotes."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5caecc80fe7add', 'les_9277e9be997c2a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Tangent gives slope from an angle (a ramp''s grade), and a rotating lighthouse beam''s position along a straight shoreline follows a tangent curve."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0fa6e4eb683533', 'les_9277e9be997c2a', 1, 'practice', 'short_text', 1, 'What is the period of $y = \tan x$? Use pi.', '{"accept":["pi","π"]}', '[]', '$\pi$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_491cc755bcf149', 'les_9277e9be997c2a', 2, 'practice', 'multiple_choice', 2, 'Where does $y = \sec x$ have vertical asymptotes?', '{"choices":["Where sin x = 0","Where cos x = 0","Where tan x = 1","Nowhere"],"answer":1}', '[]', 'Where cosine is 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0ca46141b86284', 'les_9277e9be997c2a', 3, 'practice', 'multiple_choice', 2, 'What is the range of $y = \csc x$?', '{"choices":["All reals","$[-1, 1]$","$(-\\infty, -1] \\cup [1, \\infty)$","$(0, \\infty)$"],"answer":2}', '[]', 'The reciprocal of values in $[-1, 1]$ (excluding 0).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bba5f8ef1dcb71', 'les_9277e9be997c2a', 4, 'review', 'short_text', 3, 'What is the period of $y = 3\tan\left(\frac{x}{2}\right)$? Use pi.', '{"accept":["2pi","2π"]}', '[]', '$\pi / \frac{1}{2} = 2\pi$.');
